function studioNewProject(){const groups=editorialGroups();if(!groups.length)return `${nav()}<main class="wrap"><div class="empty"><div class="emptyArt">🔒</div><strong>No tienes permisos editoriales</strong><div>Crear proyectos requiere rol Owner, Admin, Traductor o Editor.</div><div style="margin-top:12px"><button class="btn" data-v="studio">← Studio</button></div></div></main>`;return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><span class="eyebrow" style="color:var(--accent)">Studio · Beta 2</span><h2>Nuevo proyecto</h2><p>Crea la obra original y su traducción en un solo flujo.</p></div><button class="btn" data-v="studio">← Studio</button></div><div class="authShell"><div class="authVisual"><h2>De la ficha al lector.</h2><p>El proyecto empieza en borrador y solo será visible públicamente cuando publiques contenido.</p></div><div class="authPanel"><div class="field"><label>Equipo</label><select id="newGroup">${groups.map(g=>`<option value="${g.translator_groups?.id}">${esc(g.translator_groups?.name||'Equipo')}</option>`).join('')}</select></div><div class="field"><label>Título de la obra</label><input id="newNovelTitle" maxlength="220"></div><div class="field"><label>Título original</label><input id="newNovelOriginal" maxlength="220"></div><div class="field"><label>Autor</label><input id="newNovelAuthor" maxlength="160"></div><div class="field"><label>Sinopsis</label><textarea id="newNovelSynopsis" rows="6"></textarea></div><div class="field"><label>Géneros (opcional)</label><input id="newNovelGenres" placeholder="Romance, Comedia, Fantasía"></div><div class="field"><label>Etiquetas (opcional)</label><input id="newNovelTags" placeholder="school-life, isekai, slow-burn"></div><div class="field"><label>Portada</label><input id="newNovelCover" placeholder="https://..."><div class="mediaPicker"><input id="newNovelCoverFile" type="file" accept="image/jpeg,image/png,image/webp,image/gif"><div class="uploadHint">Subir directamente a El Obi del Lector · máximo 8 MB.</div></div></div><div class="field"><label>Idioma de traducción</label><input id="newTranslationLanguage" value="es"></div><button class="btn primary" id="createProject">Crear proyecto</button></div></div></main>`}
function studioSectionStats(sec){const blocks=Array.isArray(sec?.content)?sec.content:[],text=blocksToPlainText(blocks),images=blocks.filter(b=>normalizeBlock(b).type==='image').length;return{characters:text.length,images}}
function studioProjectReadOnlyView(P){return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><span class="eyebrow" style="color:var(--accent)">Studio · Consulta</span><h2>${esc(P.novels?.title||P.title||'Proyecto')}</h2><p>${esc(P.translator_groups?.name||'Equipo')} · ${esc(P.status)}</p></div><button class="btn" data-v="studio">← Studio</button></div><div class="notice"><strong>Modo solo lectura</strong><div class="muted">Tu rol puede consultar este proyecto, pero los cambios editoriales requieren Owner, Admin, Traductor o Editor.</div></div><div class="contentTree">${(P.volumes||[]).length?P.volumes.map(v=>`<div class="volumeCard"><div><span class="badge">${esc(v.status)}</span><h3>Vol. ${esc(v.volume_number)}${v.title?` · ${esc(v.title)}`:''}</h3></div><div>${(v.sections||[]).length?v.sections.map(sec=>`<div class="sectionRow"><div><div class="row"><span class="badge">${esc(sec.section_type)}</span><span class="badge">${esc(sec.status)}</span></div><strong>${esc(sec.title||'Sin título')}</strong></div></div>`).join(''):'<div class="muted">Sin secciones.</div>'}</div></div>`).join(''):'<div class="empty">Este proyecto todavía no tiene volúmenes.</div>'}</div></main>`}

