function studioProjectView(){const P=S.studioProject;if(!P)return `${nav()}<main class="wrap"><div class="empty">Cargando proyecto…</div></main>`;if(!isCurrentGroupEditor(P.group_id))return studioProjectReadOnlyView(P);return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><span class="eyebrow" style="color:var(--accent)">Studio · Proyecto</span><h2>${esc(P.novels?.title||P.title||'Proyecto')}</h2><p>${esc(P.translator_groups?.name||'Equipo')} · ${esc(P.status)}</p></div><div class="row"><button class="btn" data-media-open="${P.group_id}" data-target="novel-cover">Biblioteca multimedia</button><button class="btn" data-v="studio">← Studio</button><button class="btn" data-v="studio:import">Importar</button></div></div>
 <div class="panelGrid"><div class="panelCard"><h3>Nuevo volumen</h3><div class="field"><label>Número</label><input id="projectVolumeNumber" type="number" min="0" step=".5" value="${Math.max(0,...(P.volumes||[]).map(v=>Number(v.volume_number)||0))+1}"></div><div class="field"><label>Título</label><input id="projectVolumeTitle"></div><button class="btn primary" id="createVolume">Crear volumen</button></div><div class="panelCard"><h3>Estado de traducción</h3><p class="muted">La traducción puede permanecer activa mientras sus volúmenes/capítulos se controlan por separado.</p><span class="badge">${esc(P.status)}</span></div><div class="panelCard"><h3>Publicación</h3><p class="muted">Solo se muestra públicamente contenido con volumen y sección publicados.</p><span class="badge">Control manual</span></div></div>
 <div class="editorialBox"><h3 style="margin-top:0">Descubrimiento</h3><p class="muted">Opcional. Ayuda a que los lectores encuentren la obra.</p><div class="row"><div class="field" style="flex:1"><label>Géneros</label><input id="projectGenres" value="${esc((P.novels?.genres||[]).join(', '))}" placeholder="Romance, Fantasía"></div><div class="field" style="flex:1"><label>Etiquetas</label><input id="projectTags" value="${esc((P.novels?.tags||[]).join(', '))}" placeholder="school-life, isekai"></div></div><button class="btn" id="saveDiscoveryMeta">Guardar descubrimiento</button></div>
 <div class="editorialBox"><div class="row" style="justify-content:space-between"><div><h3 style="margin:0">Flujo editorial avanzado</h3><p class="muted" style="margin-bottom:0">Opcional. Actívalo solo si quieres historial, comparación y restauración.</p></div><label class="radio"><input type="checkbox" id="editorialModeToggle" ${P.editorial_mode?'checked':''}><span>${P.editorial_mode?'Activado':'Desactivado'}</span></label></div>${P.editorial_mode?'<div class="notice" style="margin-top:12px">Guardar y publicar directamente sigue disponible. Las revisiones son una ayuda opcional.</div>':''}</div>
 <div class="sectionHead"><div><h2>Contenido</h2><p>Volúmenes y secciones del proyecto.</p></div></div><div class="contentTree">${(P.volumes||[]).length?P.volumes.map(v=>`<div class="volumeCard"><div class="row" style="justify-content:space-between"><div><span class="badge">${esc(v.status)}</span><h3 style="margin:7px 0">Vol. ${esc(v.volume_number)}${v.title?` · ${esc(v.title)}`:''}</h3></div><div class="row"><label class="btn">Subir portada <input type="file" accept="image/jpeg,image/png,image/webp,image/gif" data-volume-cover="${v.id}" hidden></label><button class="btn" data-media-open="${P.group_id}" data-target="volume-cover:${v.id}">Elegir portada</button><button class="btn" data-new-section="${v.id}">+ Capítulo</button><button class="btn" data-import-volume="${esc(v.volume_number)}" data-import-title="${esc(v.title||'')}">Importar capítulos</button>${v.status==='published'?`<button class="btn danger" data-volume-status="${v.id}" data-status="hidden">Ocultar volumen</button>`:`<button class="btn primary" data-volume-status="${v.id}" data-status="published">Publicar volumen</button>`}</div></div><div>${(v.sections||[]).length?v.sections.map(sec=>`<div class="sectionRow"><div><div class="row"><span class="badge">${esc(sec.section_type)}</span><span class="badge">${esc(sec.status)}</span></div><strong>${esc(sec.title||'Sin título')}</strong><div class="muted">${(()=>{const st=studioSectionStats(sec);return '#'+esc(sec.section_number||'—')+' · '+st.characters.toLocaleString()+' caracteres · '+st.images+' '+(st.images===1?'imagen':'imágenes')+(sec.updated_at?' · '+esc(String(sec.updated_at).replace('T',' ').slice(0,16)):'')})()}</div></div><div class="row"><div class="sectionSort"><button class="btn" data-move-section="${sec.id}" data-dir="-1">↑</button><button class="btn" data-move-section="${sec.id}" data-dir="1">↓</button></div>${P.editorial_mode?`<button class="btn" data-preview-section="${sec.id}">Vista previa</button><button class="btn" data-history-section="${sec.id}">Historial</button>`:''}<button class="btn" data-edit-section="${sec.id}">Editar</button>${sec.status==='published'?`<button class="btn danger" data-section-status="${sec.id}" data-status="hidden">Ocultar</button>`:`<button class="btn primary" data-section-status="${sec.id}" data-status="published">Publicar</button>`}</div></div>`).join(''):'<div class="muted">Este volumen aún no tiene secciones.</div>'}</div></div>`).join(''):'<div class="empty">Crea un volumen para comenzar.</div>'}</div>
 ${P.editingSection?studioSectionEditor(P.editingSection):''}
 <div class="sectionHead"><div><h2>Enlaces externos</h2><p>Compra oficial y descargas del proyecto.</p></div></div>
 <div class="linkSections">
  <div class="linkPanel"><h3>❤️ Compra oficial</h3><p class="muted">Los enlaces nuevos quedan pendientes de verificación administrativa.</p><div class="field"><label>Tienda</label><input id="purchaseStore" placeholder="Amazon JP, BookWalker..."></div><div class="field"><label>URL</label><input id="purchaseUrl" placeholder="https://..."></div><div class="row"><div class="field" style="flex:1"><label>Volumen</label><input id="purchaseVolume" type="number" min="0" step=".5"></div><div class="field" style="flex:1"><label>Región</label><input id="purchaseRegion" placeholder="JP"></div></div><div class="row"><div class="field" style="flex:1"><label>Idioma</label><input id="purchaseLanguage" value="ja"></div><div class="field" style="flex:1"><label>Formato</label><input id="purchaseFormat" placeholder="digital / físico"></div></div><button class="btn primary" id="addPurchaseLink">Agregar enlace</button>${P.purchase_links?.length?P.purchase_links.map(l=>`<div class="sectionRow"><div><span class="badge">${l.is_verified?'Verificado':'Pendiente'}</span><a class="link" href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener">${esc(l.store_name||'Tienda')}${l.volume_number?` · Vol. ${esc(l.volume_number)}`:''}</a></div><button class="btn danger" data-delete-purchase="${l.id}">Eliminar</button></div>`).join(''):'<div class="muted" style="margin-top:12px">Sin enlaces oficiales.</div>'}</div>
  <div class="linkPanel"><h3>⬇ Descargas</h3><p class="muted">Archivos alojados externamente por el equipo.</p><div class="field"><label>Volumen</label><select id="downloadVolume">${(P.volumes||[]).map(v=>`<option value="${v.id}">Vol. ${esc(v.volume_number)}${v.title?` · ${esc(v.title)}`:''}</option>`).join('')}</select></div><div class="field"><label>Formato</label><input id="downloadFormat" placeholder="EPUB, PDF, DOCX"></div><div class="field"><label>Proveedor</label><input id="downloadProvider" placeholder="Drive, MEGA..."></div><div class="field"><label>URL</label><input id="downloadUrl" placeholder="https://..."></div><button class="btn primary" id="addDownloadLink">Agregar descarga</button>${P.download_links?.length?P.download_links.map(l=>`<div class="sectionRow"><a class="link" href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener">${esc((l.format||'Archivo').toUpperCase())}${l.provider?` · ${esc(l.provider)}`:''}</a><button class="btn danger" data-delete-download="${l.id}">Eliminar</button></div>`).join(''):'<div class="muted" style="margin-top:12px">Sin descargas.</div>'}</div>
  <div class="linkPanel"><h3>Vista pública</h3><p class="muted">Los lectores verán estos enlaces separados de la lectura integrada.</p><button class="btn" data-open="${P.id}">Ver ficha pública</button></div>
 </div></main>`}
function normalizeBlock(b){if(!b||typeof b!=='object')return{type:'paragraph',text:String(b||'')};const type=b.type||'paragraph';if(type==='image')return{type,url:b.url||'',alt:b.alt||'',caption:b.caption||''};if(type==='ruby')return{type,base:b.base||'',reading:b.reading||''};if(type==='separator')return{type};return{type,text:b.text||''}}
function blockLabel(type){return({paragraph:'Párrafo',heading:'Título',quote:'Cita',image:'Ilustración',separator:'Separador',translator_note:'Nota traductor',ruby:'Ruby/Furigana'}[type]||type)}
function blockDiffKey(b){b=normalizeBlock(b);return b.type+'|'+(b.type==='image'?(b.url||'')+'|'+(b.caption||''):b.type==='ruby'?(b.base||'')+'|'+(b.reading||''):(b.text||''))}
function blockDiff(oldBlocks,currentBlocks){const a=(oldBlocks||[]).map(normalizeBlock),b=(currentBlocks||[]).map(normalizeBlock),m=a.length,n=b.length,dp=Array.from({length:m+1},()=>Array(n+1).fill(0));for(let x=m-1;x>=0;x--)for(let y=n-1;y>=0;y--)dp[x][y]=blockDiffKey(a[x])===blockDiffKey(b[y])?dp[x+1][y+1]+1:Math.max(dp[x+1][y],dp[x][y+1]);const out=[];let x=0,y=0;while(x<m||y<n){if(x<m&&y<n&&blockDiffKey(a[x])===blockDiffKey(b[y])){out.push({kind:'same',old:a[x],current:b[y]});x++;y++}else if(y<n&&(x>=m||dp[x][y+1]>=dp[x+1]?.[y]))out.push({kind:'added',current:b[y++]});else if(x<m)out.push({kind:'removed',old:a[x++]})}for(let k=0;k<out.length-1;k++){if(out[k].kind==='removed'&&out[k+1].kind==='added'&&out[k].old?.type===out[k+1].current?.type){out.splice(k,2,{kind:'changed',old:out[k].old,current:out[k+1].current})}}return out}
function diffBlockText(b){if(!b)return'';b=normalizeBlock(b);if(b.type==='image')return b.caption||b.alt||b.url||'Ilustración';if(b.type==='separator')return'— Separador —';if(b.type==='ruby')return `${b.base||''}（${b.reading||''}）`;return b.text||''}
function revisionHistoryPanel(){return `<div class='sectionHead'><div><h2>Historial de revisiones</h2><p>Se conservan al menos las 50 más recientes; las adicionales pueden limpiarse tras 180 días.</p></div></div><div class='list'>${S.revisionHistory.map(r=>`<div class='notice'><div class='row' style='justify-content:space-between'><div><strong>${esc(r.title||'Sin título')}</strong><div class='muted'>${esc((r.created_at||'').replace('T',' ').slice(0,16))}${r.profiles?.display_name?` · ${esc(r.profiles.display_name)}`:''}</div>${r.revision_note?`<div class='muted'>${esc(r.revision_note)}</div>`:''}</div><div class='row'><button class='btn' data-compare-revision='${r.id}' aria-label='Comparar esta revisión con la versión actual'>Comparar</button><button class='btn' data-restore-revision='${r.id}' aria-label='Restaurar esta revisión'>Restaurar</button></div></div></div>`).join('')}</div>`}
function revisionPreviewPanel(){const P=S.revisionPreview;if(!P)return'';if(P.mode==='compare'){const rows=P.diff||blockDiff(P.old||[],P.current||[]),changed=rows.filter(x=>x.kind!=='same').length;return `<div class='sectionHead'><div><h2>Diff por bloques</h2><p>${changed} cambio(s) detectado(s).</p></div><button class='btn' id='closeRevisionPreview'>Cerrar</button></div><div class='diffList'>${rows.map((x,k)=>`<div class='notice diff-${x.kind}'><div class='row'><span class='badge'>${x.kind==='added'?'Añadido':x.kind==='removed'?'Eliminado':x.kind==='changed'?'Modificado':'Sin cambios'}</span><span class='muted'>Bloque ${k+1}</span></div>${x.old?`<div class='diffOld'><strong>Anterior</strong><div>${esc(diffBlockText(x.old))}</div></div>`:''}${x.current?`<div class='diffNew'><strong>Actual</strong><div>${esc(diffBlockText(x.current))}</div></div>`:''}</div>`).join('')}</div>`}return `<div class='sectionHead'><div><h2>Vista previa</h2></div><button class='btn' id='closeRevisionPreview'>Cerrar</button></div><article class='readerPaper'>${(P.content||[]).map(renderReaderBlock).join('')}</article>`}
function studioSectionEditor(sec){if(!S.blockEditor||S.blockEditor.sectionId!==sec.id)S.blockEditor={sectionId:sec.id,blocks:(Array.isArray(sec.content)?sec.content:[]).map(normalizeBlock)};const blocks=S.blockEditor.blocks;return `<div class="sectionHead"><div><h2>Editor por bloques</h2><p>${esc(sec.title||'')}</p></div></div><div class="panelCard"><div class="field"><label for="editSectionTitle">Título</label><input id="editSectionTitle" value="${esc(sec.title||'')}"></div><div class="field"><label for="editSectionType">Tipo</label><select id="editSectionType"><option value="chapter" ${sec.section_type==='chapter'?'selected':''}>Capítulo</option><option value="prologue" ${sec.section_type==='prologue'?'selected':''}>Prólogo</option><option value="interlude" ${sec.section_type==='interlude'?'selected':''}>Interludio</option><option value="epilogue" ${sec.section_type==='epilogue'?'selected':''}>Epílogo</option><option value="afterword" ${sec.section_type==='afterword'?'selected':''}>Afterword</option><option value="extra" ${sec.section_type==='extra'?'selected':''}>Extra</option></select></div><div class="blockPalette"><button class="btn" data-add-block="paragraph" aria-label="Añadir bloque de párrafo">+ Párrafo</button><button class="btn" data-add-block="heading" aria-label="Añadir bloque de título">+ Título</button><button class="btn" data-add-block="quote" aria-label="Añadir bloque de cita">+ Cita</button><button class="btn" data-add-block="image" aria-label="Añadir bloque de ilustración">+ Ilustración</button><button class="btn" data-add-block="separator" aria-label="Añadir bloque separador">+ Separador</button><button class="btn" data-add-block="translator_note" aria-label="Añadir nota del traductor">+ Nota traductor</button><button class="btn" data-add-block="ruby" aria-label="Añadir bloque ruby o furigana">+ Ruby</button></div><div class="blockEditor">${blocks.length?blocks.map((b,i)=>renderEditorBlock(b,i)).join(''):'<div class="empty">Añade el primer bloque del capítulo.</div>'}</div>${S.studioProject?.editorial_mode?`<div class="field"><label for="revisionNote">Nota de revisión (opcional)</label><input id="revisionNote" maxlength="240" placeholder="Ej. Corrección de estilo"></div><label class="radio"><input type="checkbox" id="createRevisionOnSave" checked><span>Guardar copia anterior en el historial</span></label>`:''}<div class="row" style="margin-top:16px"><button class="btn primary" id="saveSection">Guardar cambios</button>${S.studioProject?.editorial_mode?'<button class="btn" id="previewEditingSection">Vista previa</button>':''}<button class="btn" id="closeSectionEditor">Cerrar</button></div></div>${S.studioProject?.editorial_mode&&S.revisionHistory.length?revisionHistoryPanel():''}${S.revisionPreview?revisionPreviewPanel():''}`}
function renderEditorBlock(b,i){
 const n=i+1,label=blockLabel(b.type);
 const controls=`<div class="blockActions" aria-label="Acciones del bloque ${n}"><button class="btn" type="button" data-move-block="${i}" data-dir="-1" ${i===0?'disabled':''} aria-label="Mover ${esc(label)} ${n} hacia arriba">↑</button><button class="btn" type="button" data-move-block="${i}" data-dir="1" ${i===S.blockEditor.blocks.length-1?'disabled':''} aria-label="Mover ${esc(label)} ${n} hacia abajo">↓</button><button class="btn danger" type="button" data-delete-block="${i}" aria-label="Eliminar ${esc(label)} ${n}">Eliminar</button></div>`;
 let body='';
 if(['paragraph','heading','quote','translator_note'].includes(b.type)){
  const id=`blockText-${i}`;
  body=`<div class="field"><label class="srOnly" for="${id}">${esc(label)} ${n}</label><textarea id="${id}" rows="${b.type==='paragraph'?5:3}" data-block-text="${i}" aria-label="${esc(label)} ${n}">${esc(b.text||'')}</textarea></div>`
 }else if(b.type==='image'){
  const urlId=`blockUrl-${i}`,altId=`blockAlt-${i}`,capId=`blockCaption-${i}`;
  body=`<div class="field"><label for="${urlId}">Ilustración ${n}</label><input id="${urlId}" data-block-url="${i}" value="${esc(b.url||'')}" placeholder="https://..."><div class="mediaPicker"><label class="btn" for="blockFile-${i}">Subir imagen</label><input id="blockFile-${i}" type="file" accept="image/jpeg,image/png,image/webp,image/gif" data-block-file="${i}" class="srOnly"><div class="uploadHint">Subir directamente al proyecto.</div><button class="btn" type="button" data-media-open="${S.studioProject?.group_id||''}" data-target="block:${i}">Elegir existente</button></div>${b.url?`<img class="mediaPreview" src="${esc(safeMediaUrl(b.url))}" alt="${esc((b.alt||'').trim()||'Vista previa de la ilustración')}">`:''}</div><div class="field"><label for="${altId}">Texto alternativo</label><input id="${altId}" data-block-alt="${i}" value="${esc(b.alt||'')}" aria-describedby="blockAltHelp-${i}"><div class="uploadHint" id="blockAltHelp-${i}">Describe la información relevante de la imagen; déjalo vacío solo si es decorativa.</div></div><div class="field"><label for="${capId}">Pie de imagen</label><input id="${capId}" data-block-caption="${i}" value="${esc(b.caption||'')}"></div>`
 }else if(b.type==='ruby'){
  body=`<div class="row"><div class="field" style="flex:1"><label for="blockBase-${i}">Texto base</label><input id="blockBase-${i}" data-block-base="${i}" value="${esc(b.base||'')}"></div><div class="field" style="flex:1"><label for="blockReading-${i}">Lectura / furigana</label><input id="blockReading-${i}" data-block-reading="${i}" value="${esc(b.reading||'')}"></div></div>`
 }else body='<div class="blockPreview" aria-label="Separador">— Separador —</div>';
 return `<section class="blockItem" aria-labelledby="blockLabel-${i}"><div class="blockTop"><span class="blockType" id="blockLabel-${i}">${esc(label)} ${n}</span>${controls}</div>${body}</section>`
}
function addEditorBlock(type){if(!S.blockEditor)return;const map={paragraph:{type,text:''},heading:{type,text:''},quote:{type,text:''},image:{type,url:'',alt:'',caption:''},separator:{type},translator_note:{type,text:''},ruby:{type,base:'',reading:''}};S.blockEditor.blocks.push(map[type]||{type:'paragraph',text:''});render()}
function moveEditorBlock(i,dir){if(!S.blockEditor)return;const j=i+dir;if(j<0||j>=S.blockEditor.blocks.length)return;[S.blockEditor.blocks[i],S.blockEditor.blocks[j]]=[S.blockEditor.blocks[j],S.blockEditor.blocks[i]];render()}
function deleteEditorBlock(i){if(!S.blockEditor)return;S.blockEditor.blocks.splice(i,1);render()}
function syncEditorInputs(){if(!S.blockEditor)return;S.blockEditor.blocks.forEach((b,i)=>{if(['paragraph','heading','quote','translator_note'].includes(b.type)){const el=document.querySelector(`[data-block-text="${i}"]`);if(el)b.text=el.value}else if(b.type==='image'){const u=document.querySelector(`[data-block-url="${i}"]`),a=document.querySelector(`[data-block-alt="${i}"]`),c=document.querySelector(`[data-block-caption="${i}"]`);if(u)b.url=u.value;if(a)b.alt=a.value;if(c)b.caption=c.value}else if(b.type==='ruby'){const ba=document.querySelector(`[data-block-base="${i}"]`),r=document.querySelector(`[data-block-reading="${i}"]`);if(ba)b.base=ba.value;if(r)b.reading=r.value}})}
function renderReaderBlock(b){b=normalizeBlock(b);if(b.type==='heading')return `<h2 class="readerHeading">${esc(b.text||'')}</h2>`;if(b.type==='quote')return `<blockquote>${esc(b.text||'')}</blockquote>`;if(b.type==='separator')return '<hr aria-hidden="true">';if(b.type==='translator_note')return `<aside class="translatorNote" aria-label="Nota del traductor"><strong>Nota del traductor</strong><div>${esc(b.text||'')}</div></aside>`;if(b.type==='ruby')return `<p><ruby>${esc(b.base||'')}<rp>(</rp><rt>${esc(b.reading||'')}</rt><rp>)</rp></ruby></p>`;if(b.type==='image'&&b.url){const alt=String(b.alt??'').trim();return `<figure><img src="${esc(safeMediaUrl(b.url))}" alt="${esc(alt||'Ilustración del capítulo')}" loading="lazy" decoding="async">${b.caption?`<figcaption>${esc(b.caption)}</figcaption>`:''}</figure>`}return `<p>${esc(b.text||'')}</p>`}
function importSteps(){const order=[['file','Archivo'],['analysis','Análisis'],['structure','Estructura'],['review','Revisión'],['edit','Edición'],['publish','Guardar']],current=order.findIndex(([k])=>k===S.importState.step);return `<aside class="importSteps" aria-label="Progreso de importación">${order.map(([k,label],i)=>`<div class="importStep ${i===current?'active':i<current?'done':''}"${i===current?' aria-current="step"':''}><span class="stepDot" aria-hidden="true">${i<current?'✓':i+1}</span><span>${label}</span></div>`).join('')}</aside>`}
function studioImport(){if(!editorialGroups().length)return `${nav()}<main class="wrap"><div class="empty"><div class="emptyArt">🔒</div><strong>No tienes permisos para importar</strong><div>La importación requiere rol Owner, Admin, Traductor o Editor.</div><div style="margin-top:12px"><button class="btn" data-v="studio">← Studio</button></div></div></main>`;return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><span class="eyebrow" style="color:var(--accent)">Studio · Importador</span><h2>Importar volumen o capítulo</h2><p>Archivo → Análisis → Estructura → Revisión → Edición → Borrador</p></div><button class="btn" data-v="studio">← Studio</button></div><div class="importShell">${importSteps()}<section class="importPanel">${importStepView()}</section></div></main>`}
function importBlockStats(blocks){const c={paragraph:0,heading:0,quote:0,image:0,separator:0,translator_note:0,ruby:0};(blocks||[]).forEach(b=>{if(c[b.type]!==undefined)c[b.type]++});return c}
function importBlockSummary(blocks){const c=importBlockStats(blocks);return Object.entries(c).filter(([,n])=>n).map(([k,n])=>`${n} ${blockLabel(k).toLowerCase()}`).join(' · ')||'Sin bloques'}
function importMediaPreview(blocks,limit=6){const imgs=(blocks||[]).filter(b=>b.type==='image'&&b.url).slice(0,limit);return imgs.length?`<div class="importImageStrip compact" aria-label="Ilustraciones de la sección">${imgs.map((b,i)=>`<figure><img src="${esc(safeMediaUrl(b.url))}" alt="${esc(b.alt||('Ilustración '+(i+1)))}"><figcaption>${esc(b.caption||('Imagen '+(i+1)))}</figcaption></figure>`).join('')}</div>`:''}
function importStepView(){const I=S.importState;if(I.step==='file')return `<h3>1. Selecciona el archivo</h3><p class="muted">DOCX, EPUB y PDF (máximo 80 MB). DOCX/EPUB conservan estructura editorial cuando es posible; PDF se importa de forma conservadora como texto. Los archivos comprimidos con expansión anómala se rechazan por seguridad.</p><label class="dropZone" for="importFile"><div style="font-size:2.2rem">⇧</div><strong>Seleccionar archivo</strong><div class="muted">DOCX · EPUB · PDF</div><input id="importFile" type="file" accept=".docx,.epub,.pdf" hidden></label>${I.file?`<div class="fileBadge">📄 ${esc(I.name)} · ${Math.max(1,Math.round(I.file.size/1024))} KB</div><div class="wizardActions"><span class="muted">${esc(I.type.toUpperCase())}</span><button class="btn primary" id="analyzeImport">Analizar archivo</button></div>`:''}${I.message?`<p class="muted">${esc(I.message)}</p>`:''}`;
if(I.step==='analysis'){const c=importBlockStats(I.parsedBlocks);return `<h3>2. Análisis editorial</h3><div class="importSummary"><div class="infoBox"><small>Archivo</small><b>${esc(I.name)}</b></div><div class="infoBox"><small>Caracteres</small><b>${I.text.length.toLocaleString()}</b></div><div class="infoBox"><small>Bloques detectados</small><b>${I.parsedBlocks.length}</b></div></div><div class="row" style="margin:12px 0;flex-wrap:wrap">${Object.entries(c).filter(([,n])=>n).map(([k,n])=>`<span class="badge">${n} ${esc(blockLabel(k))}</span>`).join('')}</div>${c.image?'<div class="importImageStrip" aria-label="Ilustraciones detectadas">'+I.parsedBlocks.filter(b=>b.type==="image"&&b.url).slice(0,12).map((b,i)=>`<figure><img src="${esc(safeMediaUrl(b.url))}" alt="${esc(b.alt||("Ilustración "+(i+1)))}"><figcaption>${esc(b.caption||("Imagen "+(i+1)))}</figcaption></figure>`).join("")+'</div>':''}${I.warnings?.length?`<div class="notice"><strong>Advertencias</strong>${I.warnings.map(w=>`<div class="muted">• ${esc(w)}</div>`).join('')}</div>`:''}<div class="importPreview">${esc(I.text.slice(0,12000))}${I.text.length>12000?'\n\n[… vista previa recortada …]':''}</div><div class="wizardActions"><button class="btn" data-import-back="file">← Archivo</button><button class="btn primary" id="detectStructure">Detectar capítulos</button></div>`}
if(I.step==='structure')return `<h3>3. Estructura detectada</h3><p class="muted">Ajusta títulos y tipos. Los bloques ricos se conservarán al guardar.</p><div class="sectionEditor">${I.sections.map((x,i)=>`<div class="sectionDraft"><div class="row"><span class="badge">${i+1}</span><input style="flex:1;padding:9px;border:1px solid var(--line);border-radius:10px;background:var(--panel);color:var(--text)" data-sec-title="${i}" value="${esc(x.title)}"><select data-sec-type="${i}"><option value="chapter" ${x.section_type==='chapter'?'selected':''}>Capítulo</option><option value="prologue" ${x.section_type==='prologue'?'selected':''}>Prólogo</option><option value="interlude" ${x.section_type==='interlude'?'selected':''}>Interludio</option><option value="epilogue" ${x.section_type==='epilogue'?'selected':''}>Epílogo</option><option value="afterword" ${x.section_type==='afterword'?'selected':''}>Afterword</option><option value="extra" ${x.section_type==='extra'?'selected':''}>Extra</option></select></div><div class="row" style="margin-top:8px;flex-wrap:wrap"><button class="btn" data-import-move="${i}" data-dir="-1" ${i===0?'disabled':''}>↑</button><button class="btn" data-import-move="${i}" data-dir="1" ${i===I.sections.length-1?'disabled':''}>↓</button><button class="btn" data-import-merge="${i}" ${i===0?'disabled':''}>Unir con anterior</button><button class="btn danger" data-import-delete="${i}">Eliminar</button></div><p class="muted">${esc(importBlockSummary(x.blocks))}</p>${importMediaPreview(x.blocks,4)}<div class="importPreview" style="max-height:150px">${esc(blocksToPlainText(x.blocks).slice(0,500))}</div></div>`).join('')}</div><div class="wizardActions"><button class="btn" data-import-back="analysis">← Análisis</button><button class="btn primary" id="reviewStructure">Revisar estructura</button></div>`;
if(I.step==='review')return `<h3>4. Revisión</h3><div class="field"><label>Proyecto / traducción</label><select id="importTranslation"><option value="">Selecciona…</option>${S.studioTranslations.filter(t=>isCurrentGroupEditor(t.group_id)).map(t=>`<option value="${t.id}" ${I.translationId===t.id?'selected':''}>${esc(t.novels?.title||t.title||'Proyecto')} · ${esc(t.translator_groups?.name||'Equipo')}</option>`).join('')}</select></div><div class="row"><div class="field" style="flex:1"><label>Número de volumen</label><input id="importVolumeNumber" type="number" min="0" step="0.5" value="${esc(I.volumeNumber)}"></div><div class="field" style="flex:2"><label>Título del volumen</label><input id="importVolumeTitle" value="${esc(I.volumeTitle)}"></div></div><div class="field"><label>Si el volumen ya existe</label><select id="importExistingAction"><option value="append" ${I.existingAction==='append'?'selected':''}>Agregar después de las secciones existentes</option><option value="replace" ${I.existingAction==='replace'?'selected':''}>Reemplazar las secciones existentes</option></select></div><div class="notice"><strong>${I.sections.length} secciones · ${I.sections.reduce((n,x)=>n+(x.blocks?.length||0),0)} bloques</strong><div class="muted">Todo se guardará como borrador. Nada se publicará automáticamente ni se sobrescribirá sin tu selección.</div></div><div class="wizardActions"><button class="btn" data-import-back="structure">← Estructura</button><button class="btn primary" id="goEditImport">Continuar a edición</button></div>`;
if(I.step==='edit')return `<h3>5. Revisión de bloques</h3><p class="muted">Puedes corregir el texto aquí. Si modificas el texto, esa sección se reconstruirá como párrafos simples para que los cambios sí se guarden.</p><div class="sectionEditor">${I.sections.map((x,i)=>`<div class="sectionDraft"><div class="row"><strong>${esc(x.title)}</strong><span class="badge">${esc(x.section_type)}</span></div><div class="muted">${esc(importBlockSummary(x.blocks))}</div>${importMediaPreview(x.blocks,6)}<textarea data-sec-body="${i}">${esc(blocksToPlainText(x.blocks))}</textarea><div class="row" style="margin-top:8px"><button class="btn" data-import-split="${i}">Dividir en cursor</button><span class="muted">Coloca el cursor en el punto de corte.</span></div></div>`).join('')}</div><div class="wizardActions"><button class="btn" data-import-back="review">← Revisión</button><button class="btn primary" id="goPublishImport">Revisar guardado</button></div>`;
return `<h3>6. Guardar borradores</h3><p class="muted">Esta acción escribe los bloques detectados en Supabase con estado <b>draft</b>.</p><div class="notice"><strong>${esc(I.name)}</strong><div class="muted">${I.sections.length} secciones · ${I.sections.reduce((n,x)=>n+(x.blocks?.length||0),0)} bloques → Volumen ${esc(I.volumeNumber)}</div></div>${I.message?`<div class="status ${/completada/i.test(I.message)?'ok':'bad'}" style="margin-top:12px">${esc(I.message)}</div>`:''}<div class="wizardActions"><button class="btn" data-import-back="edit">← Edición</button><button class="btn primary" id="saveImportDrafts" ${I.busy?'disabled':''}>${I.busy?'Guardando…':'Guardar como borrador'}</button></div>`}
function notificationTypeLabel(t){return({new_publication:'Nueva publicación',comment_reply:'Respuesta',team_application:'Equipo',system:'Sistema'}[t]||'Aviso')}
function notificationAction(n){if(n.section_id&&n.translation_id)return `<button class="btn primary" data-note-open-section="${n.section_id}" data-translation="${n.translation_id}">Abrir capítulo</button>`;if(n.translation_id)return `<button class="btn primary" data-open="${n.translation_id}">Ver obra</button>`;if(n.notification_type==='team_application')return `<button class="btn" data-v="auth">Ver mi cuenta</button>`;if(n.notification_type==='system')return `<button class="btn" data-v="beta">Abrir Beta</button>`;return''}
function notifications(){const unread=S.notes.filter(x=>!x.read_at).length,P=S.notificationPrefs;return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><h2>Notificaciones</h2><p>Novedades de tus lecturas, comentarios, equipos y cuenta.</p></div><div class="row">${unread?`<button class="btn primary" id="markAllNotificationsRead">Marcar todas leídas</button>`:''}<button class="btn" id="clearReadNotifications">Limpiar leídas</button></div></div><div class="notificationPrefs"><label class="notificationPref"><input type="checkbox" data-notification-pref="new_publications" ${P.new_publications?'checked':''}> <strong>Nuevas publicaciones</strong><div class="muted">Capítulos de obras, traducciones y equipos que sigues.</div></label><label class="notificationPref"><input type="checkbox" data-notification-pref="comment_replies" ${P.comment_replies?'checked':''}> <strong>Respuestas</strong><div class="muted">Cuando alguien responde a uno de tus comentarios.</div></label><label class="notificationPref"><input type="checkbox" data-notification-pref="team_updates" ${P.team_updates?'checked':''}> <strong>Equipos</strong><div class="muted">Aprobación o rechazo de solicitudes de equipo.</div></label><label class="notificationPref"><input type="checkbox" data-notification-pref="system_updates" ${P.system_updates?'checked':''}> <strong>Sistema</strong><div class="muted">Resolución de reportes Beta y avisos importantes.</div></label></div><div class="list">${S.notes.length?S.notes.map(n=>`<div class="notice notificationItem ${!n.read_at?'unread':''}"><div class="row"><span class="badge">${esc(notificationTypeLabel(n.notification_type))}</span><strong>${esc(n.title)}</strong>${!n.read_at?'<span class="badge">Nueva</span>':''}</div><div class="muted">${esc(n.body||'')}</div><div class="muted">${esc((n.created_at||'').replace('T',' ').slice(0,16))}</div><div class="notificationActions">${notificationAction(n)}${!n.read_at?`<button class="btn" data-read="${n.id}">Marcar leída</button>`:''}<button class="btn danger" data-delete-note="${n.id}">Eliminar</button></div></div>`).join(''):'<div class="empty"><div class="emptyArt">🔔</div><strong>Todo al día</strong><div>No tienes notificaciones.</div></div>'}</div></main>`}

function betaView(){
 if(!S.user)return `${nav()}<main class="wrap"><div class="empty"><div class="emptyArt">🧪</div><strong>Centro Beta</strong><div>Inicia sesión para ejecutar pruebas y enviar feedback.</div><div style="margin-top:12px"><button class="btn primary" data-v="auth">Iniciar sesión</button></div></div></main>`;
 const checks=S.betaChecks.length?`<div class="list">${S.betaChecks.map(x=>`<div class="notice"><div class="row"><span class="badge">${x.ok?'OK':'Fallo'}</span><strong>${esc(x.label)}</strong></div><div class="muted">${esc(x.detail||'')}</div></div>`).join('')}</div>`:'<div class="empty"><div class="emptyArt">✓</div><strong>Aún no ejecutas el diagnóstico</strong><div>Las pruebas son de lectura y no modifican contenido.</div></div>';
 return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><span class="eyebrow" style="color:var(--accent)">Centro Beta</span><h2>Centro de pruebas</h2><p>Comprueba las conexiones principales y reporta cualquier problema desde aquí.</p></div><button class="btn primary" id="runBetaChecks">Ejecutar diagnóstico</button></div>
 <div class="panelGrid"><div class="panelCard"><h3>Estado de la sesión</h3><p class="muted">${S.user?`Conectado como ${esc(S.user.email||S.profile?.display_name||'usuario')}`:'Sin sesión'}</p><span class="badge">${S.online?'En línea':'Sin conexión'}</span></div><div class="panelCard"><h3>Biblioteca</h3><p class="muted">${S.library.length} títulos sincronizados.</p></div><div class="panelCard"><h3>Studio</h3><p class="muted">${S.groups.length?`${S.groups.length} equipos vinculados.`:'Sin equipo aprobado.'}</p></div><div class="panelCard"><h3>QA de plataforma</h3><p class="muted">RLS endurecido, progreso sin regresiones, filtros restaurados y publicación encadenada protegida.</p><span class="badge">Pre-producción</span></div></div>
 <div class="sectionHead"><div><h2>Diagnóstico E2E</h2><p>Frontend → Supabase → sesión → perfil → biblioteca → Studio.</p></div></div>${checks}
 <div class="sectionHead"><div><h2>Enviar feedback</h2><p>El reporte quedará asociado únicamente a tu cuenta.</p></div></div>
 <div class="authShell betaFeedbackShell"><div class="authVisual"><h2>Ayuda a pulir El Obi del Lector</h2><p>Describe qué estabas haciendo y qué esperabas que ocurriera.</p></div><div class="authPanel"><div class="field"><label>Categoría</label><select id="betaCategory"><option value="bug">Error</option><option value="ux">Diseño / experiencia</option><option value="content">Contenido</option><option value="performance">Rendimiento</option><option value="other">Otro</option></select></div><div class="field"><label>Título</label><input id="betaTitle" maxlength="120" placeholder="Ej. No puedo guardar en la biblioteca"></div><div class="field"><label>Descripción</label><textarea id="betaDescription" rows="6" maxlength="4000" placeholder="Pasos para reproducir el problema..."></textarea></div><button class="btn primary" id="submitBetaFeedback">Enviar reporte</button></div></div>
 ${S.betaFeedback.length?`<div class="sectionHead"><div><h2>Mis reportes</h2></div></div><div class="list">${S.betaFeedback.map(f=>`<div class="notice"><div class="row"><span class="badge">${esc(f.status)}</span><strong>${esc(f.title)}</strong></div><div class="muted">${esc(f.category)} · ${esc((f.created_at||'').slice(0,10))}</div><p>${esc(f.description)}</p>${f.admin_note?`<div class="muted">Nota admin: ${esc(f.admin_note)}</div>`:''}</div>`).join('')}</div>`:''}
 </main>`
}
function adminBeta(){return `<div class="list">${S.adminBetaFeedback.length?S.adminBetaFeedback.map(f=>`<div class="adminApp"><div class="row"><span class="badge">${esc(f.status)}</span><strong>${esc(f.title)}</strong></div><div class="muted">${esc(f.category)} · ${esc((f.created_at||'').replace('T',' ').slice(0,19))}</div><p>${esc(f.description)}</p><div class="muted">${esc(f.profiles?.display_name||f.profiles?.username||f.user_id)}</div>${f.admin_note?`<div class="notice">Nota admin: ${esc(f.admin_note)}</div>`:''}<div class="row"><button class="btn" data-beta-status="${f.id}" data-status="reviewing">Revisando</button><button class="btn primary" data-beta-status="${f.id}" data-status="resolved">Resuelto</button><button class="btn danger" data-beta-status="${f.id}" data-status="dismissed">Descartar</button></div></div>`).join(''):'<div class="empty">No hay reportes Beta.</div>'}</div>`}

function publicProfileView(){const P=S.publicProfile;if(!P)return `${nav()}<main class="wrap"><div class="empty">Cargando perfil…</div></main>`;return `${nav()}<main class="wrap">${status()}<section class="profileHero"><div class="profileAvatar">${P.avatar_url?`<img src="${esc(safeUrl(P.avatar_url))}" alt="Avatar de ${esc(P.display_name||P.username||'usuario')}">`:esc((P.display_name||P.username||'U').slice(0,1))}</div><div><h1 style="font-family:Georgia,serif;margin:0 0 6px">${esc(P.display_name||P.username||'Usuario')}</h1>${P.username?`<div class="muted">@${esc(P.username)}</div>`:''}<p>${esc(P.bio||'Sin biografía pública.')}</p></div></section>${P.public_library?`<div class="sectionHead"><div><h2>Biblioteca pública</h2><p>Lecturas que esta persona decidió compartir.</p></div></div>${P.library?.length?`<div class="libraryList">${P.library.map(x=>{const t=x.translations;return `<div class="libraryCard"><div class="libraryThumb">${t?.novels?.cover_url?`<img src="${esc(safeMediaUrl(t.novels.cover_url))}" alt="Portada de ${esc(t.novels.title||t.title||'novela')}">`:`<span class="libraryThumbFallback" aria-hidden="true">${esc((t?.novels?.title||t?.title||'N').slice(0,2))}</span>`}</div><div class="libraryMeta"><span class="statusPill">${esc(statusLabel(x.status))}</span><h3>${esc(t?.novels?.title||t?.title||'Novela')}</h3><div class="muted">${esc(t?.translator_groups?.name||'Traducción')}</div></div><button class="btn" data-open="${x.translation_id}">Ver obra</button></div>`}).join('')}</div>`:'<div class="empty">No hay lecturas públicas.</div>'}`:'<div class="sectionHead"><div><h2>Biblioteca</h2></div></div><div class="empty">Esta biblioteca es privada.</div>'}${P.public_activity?`<div class="sectionHead"><div><h2>Actividad reciente</h2><p>Progreso que esta persona eligió compartir.</p></div></div><div class="activityList">${P.activity?.length?P.activity.map(a=>`<div class="activityItem"><div class="row"><span class="badge">${esc(Math.round(Number(a.progress_percent||0)))}%</span><strong>${esc(a.translations?.novels?.title||a.translations?.title||'Lectura')}</strong></div><div class="muted">Actualizado ${esc((a.updated_at||'').replace('T',' ').slice(0,16))}</div></div>`).join(''):'<div class="empty">Sin actividad pública reciente.</div>'}</div>`:'<div class="sectionHead"><div><h2>Actividad</h2></div></div><div class="empty">La actividad de lectura es privada.</div>'}</main>`}
function adminTabs(){return `<div class="adminToolbar">${[['overview','Resumen'],['applications','Solicitudes'],['users','Usuarios'],['teams','Equipos'],['reports','Reportes'],['content','Contenido'],['links','Enlaces oficiales'],['beta','Beta'],['audit','Auditoría']].map(([k,l])=>`<button class="btn ${S.adminTab===k?'primary':''}" data-admin-tab="${k}">${l}</button>`).join('')}</div>`}
function adminOverview(){const pendingLinks=S.adminPurchaseLinks.filter(x=>!x.is_verified).length;return `<div class="kpis"><div class="kpi"><b>${S.apps.filter(x=>x.status==='pending').length}</b><span>solicitudes pendientes</span></div><div class="kpi"><b>${S.adminReports.filter(x=>x.status==='pending').length}</b><span>reportes pendientes</span></div><div class="kpi"><b>${pendingLinks}</b><span>enlaces por verificar</span></div><div class="kpi"><b>${S.adminBetaFeedback.filter(x=>x.status==='open').length}</b><span>feedback abierto</span></div></div><div class="adminGrid"><div class="panelCard"><div class="adminSectionTitle">Solicitudes</div><h3>${S.apps.filter(x=>x.status==='pending').length} pendientes</h3><button class="btn" data-admin-tab="applications">Revisar</button></div><div class="panelCard"><div class="adminSectionTitle">Moderación</div><h3>${S.adminReports.filter(x=>x.status==='pending').length} reportes</h3><button class="btn" data-admin-tab="reports">Abrir</button></div><div class="panelCard"><div class="adminSectionTitle">Compra oficial</div><h3>${pendingLinks} pendientes</h3><button class="btn" data-admin-tab="links">Verificar</button></div><div class="panelCard"><div class="adminSectionTitle">Beta</div><h3>${S.adminBetaFeedback.filter(x=>x.status==='open').length} abiertas</h3><button class="btn" data-admin-tab="beta">Revisar</button></div></div>`}
function adminApplications(){return `<div class="list">${S.apps.length?S.apps.map(a=>`<div class="adminApp"><div class="row"><span class="badge">${esc(a.status)}</span><strong>${esc(a.requested_name)}</strong></div><div class="muted">${esc(a.profiles?.display_name||a.profiles?.username||a.applicant_id)} · ${esc((a.created_at||'').slice(0,10))}</div><p>${esc(a.description||'Sin descripción')}</p>${a.website_url?`<a class="link" href="${esc(safeUrl(a.website_url))}" target="_blank" rel="noopener">Sitio declarado ↗</a>`:''}${a.admin_note?`<div class="notice">Nota: ${esc(a.admin_note)}</div>`:''}${a.status==='pending'?`<div class="field"><label>Nota administrativa</label><input data-app-note="${a.id}" placeholder="Opcional"></div><div class="row"><button class="btn primary" data-approve="${a.id}">Aprobar</button><button class="btn danger" data-reject="${a.id}">Rechazar</button></div>`:''}</div>`).join(''):'<div class="empty">No hay solicitudes.</div>'}</div>`}
function adminUsers(){return `<div class="list">${S.adminUsers.length?S.adminUsers.map(u=>`<div class="adminApp"><div class="row"><strong>${esc(u.display_name||u.username||'Usuario')}</strong><span class="badge">${esc(u.account_type||'reader')}</span></div>${u.username?`<div class="muted">@${esc(u.username)}</div>`:''}<div class="muted">${esc(u.id)}</div></div>`).join(''):'<div class="empty">Todavía no hay usuarios.</div>'}</div>`}
function adminTeams(){return `<div class="list">${S.adminTeams.length?S.adminTeams.map(g=>`<div class="adminApp"><h3>${esc(g.name)}</h3><div class="muted">@${esc(g.slug)}</div><p class="muted">${esc(g.description||'Sin descripción')}</p></div>`).join(''):'<div class="empty">Todavía no hay equipos.</div>'}</div>`}
function adminReports(){return `<div class="list">${S.adminReports.length?S.adminReports.map(r=>`<div class="adminApp"><div class="row"><span class="badge">${esc(r.status)}</span><strong>Reporte de comentario</strong></div><p>${esc(r.reason||'Sin motivo')}</p><div class="notice">${esc(r.comments?.body||'Comentario no disponible')}</div>${r.status==='pending'?`<div class="row"><button class="btn primary" data-report-review="${r.id}">Revisado</button><button class="btn" data-report-dismiss="${r.id}">Descartar</button>${r.comment_id?`<button class="btn danger" data-comment-delete="${r.comment_id}" data-report-id="${r.id}">Eliminar comentario</button>`:''}</div>`:''}</div>`).join(''):'<div class="empty">No hay reportes.</div>'}</div>`}
function adminContent(){return `<div class="sectionHead"><div><h2>Traducciones</h2></div></div><div class="list">${S.adminContent.length?S.adminContent.map(t=>`<div class="adminApp"><div class="row"><span class="badge">${esc(t.status)}</span><strong>${esc(t.novels?.title||t.title||'Traducción')}</strong></div><div class="muted">${esc(t.translator_groups?.name||'Sin equipo')}</div><div class="row">${t.status==='withdrawn'?`<button class="btn primary" data-translation-status="${t.id}" data-status="active">Restaurar</button>`:`<button class="btn danger" data-translation-status="${t.id}" data-status="withdrawn">Ocultar</button>`}</div></div>`).join(''):'<div class="empty">No hay traducciones.</div>'}</div><div class="sectionHead"><div><h2>Volúmenes</h2></div></div><div class="list">${S.adminVolumes.length?S.adminVolumes.map(v=>`<div class="adminApp"><div class="row"><span class="badge">${esc(v.status)}</span><strong>${esc(v.translations?.novels?.title||'Obra')} · Vol. ${esc(v.volume_number)}</strong></div><div class="row">${v.status==='hidden'?`<button class="btn primary" data-admin-volume="${v.id}" data-status="draft">Restaurar</button>`:`<button class="btn danger" data-admin-volume="${v.id}" data-status="hidden">Ocultar</button>`}</div></div>`).join(''):'<div class="empty">No hay volúmenes.</div>'}</div><div class="sectionHead"><div><h2>Secciones</h2></div></div><div class="list">${S.adminSections.length?S.adminSections.map(x=>`<div class="adminApp"><div class="row"><span class="badge">${esc(x.status)}</span><strong>${esc(x.title||'Sección')}</strong></div><div class="muted">${esc(x.volumes?.translations?.novels?.title||'Obra')}</div><div class="row">${x.status==='hidden'?`<button class="btn primary" data-admin-section="${x.id}" data-status="draft">Restaurar</button>`:`<button class="btn danger" data-admin-section="${x.id}" data-status="hidden">Ocultar</button>`}</div></div>`).join(''):'<div class="empty">No hay secciones.</div>'}</div>`}
function adminLinks(){return `<div class="list">${S.adminPurchaseLinks.length?S.adminPurchaseLinks.map(l=>`<div class="adminApp"><div class="row"><span class="badge">${l.is_verified?'Verificado':'Pendiente'}</span><strong>${esc(l.store_name||'Tienda')}</strong></div><div>${esc(l.novels?.title||'Obra')}${l.volume_number?` · Vol. ${esc(l.volume_number)}`:''}</div><div class="muted">${esc(l.translator_groups?.name||'Equipo')}</div><a class="link" href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener">${esc(l.url)} ↗</a><div class="row">${l.is_verified?`<button class="btn" data-purchase-verify="${l.id}" data-verified="false">Quitar verificación</button>`:`<button class="btn primary" data-purchase-verify="${l.id}" data-verified="true">Verificar</button>`}<button class="btn danger" data-admin-delete-link="${l.id}">Eliminar</button></div></div>`).join(''):'<div class="empty">No hay enlaces oficiales.</div>'}</div>`}
function adminAudit(){return `<div class="list">${S.adminAudit.length?S.adminAudit.map(a=>`<div class="notice"><div class="row"><span class="badge">${esc(a.action_type)}</span><strong>${esc(a.target_type)}</strong></div><div class="muted">${esc((a.created_at||'').replace('T',' ').slice(0,19))}</div>${a.details&&Object.keys(a.details).length?`<details><summary>Detalles</summary><div class="auditDetails">${esc(JSON.stringify(a.details))}</div></details>`:''}</div>`).join(''):'<div class="empty">Todavía no hay acciones administrativas.</div>'}</div>`}
function admin(){if(!S.admin)return `${nav()}<main class="wrap"><div class="empty"><div class="emptyArt">🔒</div><strong>Acceso restringido</strong><div>Esta sección requiere permisos de administración.</div></div></main>`;const body=S.adminTab==='applications'?adminApplications():S.adminTab==='users'?adminUsers():S.adminTab==='teams'?adminTeams():S.adminTab==='reports'?adminReports():S.adminTab==='content'?adminContent():S.adminTab==='links'?adminLinks():S.adminTab==='beta'?adminBeta():S.adminTab==='audit'?adminAudit():adminOverview();return `${nav()}<main class="wrap">${status()}<div class="sectionHead"><div><h2>Administración</h2><p>Moderación, solicitudes, contenido, enlaces oficiales y auditoría.</p></div></div>${adminTabs()}${body}</main>`}
function detailView(){
 const id=S.view.split(':')[1], D=String(id).startsWith('demo-')?demo.find(x=>x.id===id):(S.currentDetail?.id===id?S.currentDetail:S.catalog.find(x=>x.id===id));
 if(!D)return `${nav()}<main class="wrap">${status()}<div class="empty"><div class="emptyArt">📖</div><strong>Obra no disponible</strong><div style="margin-top:12px"><button class="btn" data-v="explore">← Explorar</button></div></div></main>`;
 const vols=(D.volumes||[]).filter(v=>v.status==='published'&&(v.sections||[]).some(sec=>sec.status==='published')).sort((a,b)=>Number(a.volume_number)-Number(b.volume_number));
 const purchase=D.links?.purchase||[],support=D.links?.support||[],downloads=D.links?.downloads||[];
 return `${nav()}<main class="wrap">${status()}<section class="detailHero">${coverMarkup(D,true)}<div class="detailInfo"><div class="row"><span class="badge">${esc((D.language_code||'es').toUpperCase())}</span>${!D.demo?`<span class="badge">${esc(translationStatusLabel(D.status))}</span>`:''}</div><h1>${esc(titleOf(D))}</h1><div class="muted">${esc(D.novels?.author_name||'Autor no indicado')}</div><p>${esc(D.novels?.synopsis||'Sin sinopsis disponible.')}</p><div class="metaTags">${(D.novels?.genres||[]).map(g=>`<span class="badge">${esc(g)}</span>`).join('')}</div><div class="row" style="margin-top:16px">${D.translator_groups?.id?`<button class="btn" data-group="${D.translator_groups.id}">Equipo: ${esc(D.translator_groups.name||'Traductor')}</button>`:''}${!D.demo?libraryButton(D.id,true):''}</div></div></section>${vols.length?`<div class="sectionHead"><div><h2>Leer</h2><p>Capítulos publicados.</p></div></div><div class="list">${vols.map(v=>`<div class="notice"><strong>Vol. ${esc(v.volume_number)}${v.title?` · ${esc(v.title)}`:''}</strong>${(v.sections||[]).filter(s=>s.status==='published').sort((a,b)=>(a.sort_order||0)-(b.sort_order||0)).map(sec=>`<div class="sectionRow"><span>${esc(sec.title||'Capítulo')}</span><button class="btn primary" data-read-section="${sec.id}" data-translation="${D.id}">Leer</button></div>`).join('')}</div>`).join('')}</div>`:D.demo?'<div class="sectionHead"><div><h2>Vista previa</h2><p>Esta ficha demostrativa todavía no tiene capítulos.</p></div></div>':'<div class="sectionHead"><div><h2>Contenido</h2></div></div><div class="empty">Todavía no hay capítulos publicados.</div>'}${purchase.length?`<div class="sectionHead"><div><h2>❤️ Apoya al autor</h2></div></div><div class="list">${purchase.map(l=>`<div class="notice"><a class="link" href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener">${esc(l.store_name||'Tienda')}${l.volume_number?` · Vol. ${esc(l.volume_number)}`:''} ↗</a></div>`).join('')}</div>`:''}${support.length?`<div class="sectionHead"><div><h2>☕ Apoya al traductor</h2></div></div><div class="list">${support.map(l=>`<div class="notice"><a class="link" href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener">${esc(l.label||'Apoyar')} ↗</a></div>`).join('')}</div>`:''}${downloads.length?`<div class="sectionHead"><div><h2>⬇ Descargas</h2></div></div><div class="list">${downloads.map(l=>`<div class="notice"><a class="link" href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener">${esc((l.format||'Archivo').toUpperCase())}${l.provider?` · ${esc(l.provider)}`:''} ↗</a></div>`).join('')}</div>`:''}</main>`;
}
function publicGroupView(){
 const G=S.publicGroup;
 if(!G)return `${nav()}<main class="wrap">${status()}<div class="empty"><div class="emptyArt">👥</div><strong>Equipo no cargado</strong><div style="margin-top:12px"><button class="btn" data-v="explore">← Explorar</button></div></div></main>`;
 return `${nav()}<main class="wrap">${status()}<section class="profileHero"><div class="profileAvatar">${G.avatar_url?`<img src="${esc(safeMediaUrl(G.avatar_url))}" alt="Avatar del equipo ${esc(G.name)}">`:esc((G.name||'E').slice(0,1))}</div><div><h1 style="font-family:Georgia,serif;margin:0 0 6px">${esc(G.name)}</h1><p>${esc(G.description||'Equipo de traducción en El Obi del Lector.')}</p></div></section><div class="sectionHead"><div><h2>Traducciones</h2><p>Proyectos públicos del equipo.</p></div></div>${G.translations?.length?`<div class="novelGrid">${G.translations.map(card).join('')}</div>`:'<div class="empty">Este equipo todavía no tiene traducciones públicas.</div>'}${G.support_links?.length?`<div class="sectionHead"><div><h2>☕ Apoya al traductor</h2></div></div><div class="list">${G.support_links.map(l=>`<div class="notice"><a class="link" href="${esc(safeUrl(l.url))}" target="_blank" rel="noopener">${esc(l.label||'Apoyar')} ↗</a></div>`).join('')}</div>`:''}</main>`;
}
function readerView(){
 const R=S.readerSection;
 if(!R)return `${nav()}<main class="wrap"><div class="empty"><div class="emptyArt" aria-hidden="true">📖</div><strong>Capítulo no disponible</strong><div style="margin-top:12px"><button class="btn" data-v="library">← Biblioteca</button></div></div></main>`;
 const ns=R.navigation||[],i=ns.findIndex(x=>x.id===R.id),prev=i>0?ns[i-1]:null,next=i>=0&&i<ns.length-1?ns[i+1]:null;
 const theme=S.readerPrefs.theme||'light',width=S.readerPrefs.width||'normal',lineHeight=S.readerPrefs.lineHeight||'comfortable',fontFamily=S.readerPrefs.fontFamily||'serif',paragraphSpace=S.readerPrefs.paragraphSpace||'normal';
 const roots=S.readerComments.filter(x=>!x.parent_id);
 const comment=c=>`<article class="comment ${c.parent_id?'reply':''}"><div class="row"><strong>${esc(c.profiles?.display_name||c.profiles?.username||'Usuario')}</strong><span class="muted">${esc((c.created_at||'').replace('T',' ').slice(0,16))}</span></div>${c.is_spoiler?`<button type="button" class="spoiler spoilerButton" data-reveal-spoiler aria-expanded="false" aria-label="Mostrar spoiler">${esc(c.body||'')}</button>`:`<div class="commentBody">${esc(c.body||'')}</div>`}<div class="row"><button class="btn" data-like-comment="${c.id}" aria-label="${c.liked_by_me?'Quitar me gusta':'Dar me gusta'} al comentario">${c.liked_by_me?'♥':'♡'} ${c.like_count||0}</button>${S.user?`<button class="btn" data-reply-comment="${c.id}">Responder</button><button class="btn danger" data-report-comment="${c.id}">Reportar</button>`:''}</div></article>`;
 return `${nav()}<main class="wrap"><div class="readerShell">
 <nav class="readerTop" aria-label="Navegación entre capítulos"><button class="btn" data-back-detail="${R.translation_id}">← Obra</button><div class="row">${prev?`<button class="btn" data-read-section="${prev.id}" data-translation="${R.translation_id}" aria-label="Capítulo anterior: ${esc(prev.title||'Anterior')}">← Anterior</button>`:''}${next?`<button class="btn primary" data-read-section="${next.id}" data-translation="${R.translation_id}" aria-label="Capítulo siguiente: ${esc(next.title||'Siguiente')}">Siguiente →</button>`:''}</div></nav>
 <section class="readerControls" aria-label="Preferencias de lectura">
  <label for="readerTheme">Tema</label><select id="readerTheme"><option value="light" ${theme==='light'?'selected':''}>Claro</option><option value="sepia" ${theme==='sepia'?'selected':''}>Sepia</option><option value="dark" ${theme==='dark'?'selected':''}>Oscuro</option></select>
  <label for="readerFont">Tamaño <output id="readerFontValue" for="readerFont">${Number(S.readerPrefs.fontSize||18)} px</output></label><input id="readerFont" type="range" min="14" max="30" value="${Number(S.readerPrefs.fontSize||18)}" aria-describedby="readerFontValue">
  <label for="readerWidth">Ancho</label><select id="readerWidth"><option value="narrow" ${width==='narrow'?'selected':''}>Estrecho</option><option value="normal" ${width==='normal'?'selected':''}>Normal</option><option value="wide" ${width==='wide'?'selected':''}>Ancho</option></select>
  <label for="readerLineHeight">Interlineado</label><select id="readerLineHeight"><option value="compact" ${lineHeight==='compact'?'selected':''}>Compacto</option><option value="comfortable" ${lineHeight==='comfortable'?'selected':''}>Cómodo</option><option value="relaxed" ${lineHeight==='relaxed'?'selected':''}>Amplio</option></select>
  <label for="readerFontFamily">Tipografía</label><select id="readerFontFamily"><option value="serif" ${fontFamily==='serif'?'selected':''}>Serif</option><option value="sans" ${fontFamily==='sans'?'selected':''}>Sans serif</option></select>
  <label for="readerParagraphSpace">Párrafos</label><select id="readerParagraphSpace"><option value="compact" ${paragraphSpace==='compact'?'selected':''}>Compactos</option><option value="normal" ${paragraphSpace==='normal'?'selected':''}>Normal</option><option value="wide" ${paragraphSpace==='wide'?'selected':''}>Amplios</option></select>
  <button class="btn" id="resetReaderPrefs" type="button">Restablecer</button><button class="btn" id="markReaderDone" type="button">Marcar capítulo leído</button>
 </section>
 <article class="readerPaper reader-${esc(theme)} reader-${esc(width)} reader-line-${esc(lineHeight)} reader-font-${esc(fontFamily)} reader-space-${esc(paragraphSpace)}" style="font-size:${Number(S.readerPrefs.fontSize||18)}px" aria-labelledby="chapterTitle"><div class="readerMeta">${esc(R.novel_title||'El Obi del Lector')}${R.volume_number!=null?` · Vol. ${esc(R.volume_number)}`:''}</div><h1 id="chapterTitle">${esc(R.title||'Capítulo')}</h1>${(R.content||[]).map(renderReaderBlock).join('')}</article>
 <section class="commentBox" aria-labelledby="commentsTitle"><h2 id="commentsTitle">Comentarios</h2>${S.user?`<div class="field"><label for="newCommentBody">Escribe un comentario</label><textarea id="newCommentBody" rows="4"></textarea></div><label class="radio"><input type="checkbox" id="newCommentSpoiler"><span>Contiene spoiler</span></label><button class="btn primary" id="postComment">Publicar comentario</button>`:'<p class="muted">Inicia sesión para comentar.</p>'}<div style="margin-top:18px">${roots.length?roots.map(c=>comment(c)+S.readerComments.filter(r=>r.parent_id===c.id).map(comment).join('')).join(''):'<div class="muted">Todavía no hay comentarios.</div>'}</div></section>
 </div></main>`;
}
function accessibilityViewTitle(){
 if(S.view==='home')return'Inicio';
 if(S.view==='explore')return'Explorar';
 if(S.view==='library')return'Biblioteca';
 if(S.view==='auth')return S.user?'Perfil':'Acceso';
 if(S.view==='application')return'Solicitud de equipo';
 if(S.view==='studio')return'Studio';
 if(S.view==='studio:import')return'Importar';
 if(S.view==='studio:new')return'Nuevo proyecto';
 if(S.view==='notifications')return'Avisos';
 if(S.view==='beta')return'Beta';
 if(S.view==='admin')return'Administración';
 if(S.view.startsWith('reader:'))return S.readerSection?.title||'Lector';
 if(S.view.startsWith('detail:'))return titleOf(S.currentDetail)||'Detalle de obra';
 if(S.view.startsWith('group:'))return S.publicGroup?.name||'Equipo';
 if(S.view.startsWith('profile:'))return S.publicProfile?.display_name||S.publicProfile?.username||'Perfil público';
 if(S.view.startsWith('studio:project:'))return S.studioProject?.novels?.title||S.studioProject?.title||'Proyecto';
 if(S.view.startsWith('studio:team:'))return S.studioTeam?.name||'Equipo';
 if(S.view.startsWith('studio:media:'))return'Biblioteca multimedia';
 return'El Obi del Lector'
}
function enhanceAccessibility(){
 const main=document.querySelector('#app main');
 if(main){main.id='mainContent';main.tabIndex=-1}
 const title=accessibilityViewTitle();
 if(main&&!main.querySelector('h1')){const h=document.createElement('h1');h.className='srOnly';h.textContent=title;main.prepend(h)}
 document.querySelectorAll('.field').forEach((field,i)=>{const label=field.querySelector('label'),control=field.querySelector('input,select,textarea');if(!label||!control)return;if(!control.id)control.id='autoField-'+i;if(!label.htmlFor)label.htmlFor=control.id});
 const nameControl=(selector,label)=>document.querySelectorAll(selector).forEach(el=>{if(!el.getAttribute('aria-label')&&!el.getAttribute('aria-labelledby'))el.setAttribute('aria-label',label)});
 nameControl('select[data-library-status]','Estado de lectura');
 nameControl('select[data-member-role]','Rol del miembro');
 nameControl('input[type="file"]','Seleccionar archivo');
 nameControl('[data-sec-title]','Título de la sección importada');
 nameControl('[data-sec-type]','Tipo de sección importada');
 nameControl('[data-sec-body]','Contenido de la sección importada');
 document.querySelectorAll('[data-import-move]').forEach(el=>el.setAttribute('aria-label',el.dataset.dir==='-1'?'Mover sección hacia arriba':'Mover sección hacia abajo'));
 document.querySelectorAll('.importSteps,.importPreview').forEach((el,i)=>{if(!el.hasAttribute('tabindex'))el.tabIndex=0;if(!el.getAttribute('aria-label'))el.setAttribute('aria-label',el.classList.contains('importSteps')?'Pasos de importación':'Vista previa importada '+(i+1))});
 document.title=`${title} — El Obi del Lector`;
 const announcer=document.getElementById('routeAnnouncer');
 if(announcer)announcer.textContent=`${title} cargado`;
 if(pendingRouteFocus&&main){pendingRouteFocus=false;requestAnimationFrame(()=>main.focus({preventScroll:true}))}
}
function render(){
 const app=document.getElementById('app');
 if(!app)return;
 try{
  let html=home();
  if(S.view==='explore')html=explore();
  else if(S.view==='library')html=library();
  else if(S.view==='auth')html=auth();
  else if(S.view==='application')html=application();
  else if(S.view==='studio')html=studio();
  else if(S.view==='studio:import')html=studioImport();
  else if(S.view==='studio:new')html=studioNewProject();
  else if(S.view==='notifications')html=notifications();
  else if(S.view==='beta')html=betaView();
  else if(S.view==='admin')html=admin();
  else if(S.view.startsWith('detail:'))html=detailView();
  else if(S.view.startsWith('group:'))html=publicGroupView();
  else if(S.view.startsWith('reader:'))html=readerView();
  else if(S.view.startsWith('profile:'))html=publicProfileView();
  else if(S.view.startsWith('collection:'))html=collectionView();
  else if(S.view.startsWith('studio:project:'))html=studioProjectView();
  else if(S.view.startsWith('studio:team:'))html=studioTeamView();
  else if(S.view.startsWith('studio:media:'))html=studioMediaView();
  app.innerHTML=html;
  enhanceAccessibility();
  bind();
  setNetworkBadge();
 }catch(e){
  console.error('[NLOBI render error]',e);
  app.textContent='El Obi del Lector no pudo mostrar esta vista: '+String(e?.message||e);
 }
}
