function isCjkChar(ch){return /[\u3000-\u30ff\u3400-\u9fff\uf900-\ufaff\uff00-\uffef]/u.test(ch||'')}
function pdfJoinRuns(runs){let out='';for(const run of runs){const t=String(run.str||'').trim();if(!t)continue;if(!out){out=t;continue}const a=out.slice(-1),b=t[0],noSpace=isCjkChar(a)||isCjkChar(b)||/[「『（【〈《〔［｛“‘]$/.test(a)||/^[。、，．！？：；」』）】〉》〕］｝]/.test(b);out+=(noSpace?'':' ')+t}return out.replace(/\s+([。、，．！？：；」』）】〉》])/g,'$1').replace(/([「『（【〈《])\s+/g,'$1').trim()}
function pdfTextLines(items){const groups=[];for(const it of items||[]){const y=Number(it.transform?.[5]||0),x=Number(it.transform?.[4]||0),h=Math.abs(Number(it.height||it.transform?.[3]||0));let g=groups.find(a=>Math.abs(a.y-y)<=Math.max(2,Math.min(5,(a.h||h||3)*.4)));if(!g){g={y,h,runs:[]};groups.push(g)}g.h=Math.max(g.h||0,h||0);g.runs.push({...it,_x:x})}groups.sort((a,b)=>b.y-a.y);return groups.map(g=>({text:pdfJoinRuns(g.runs.sort((a,b)=>a._x-b._x)),height:g.h})).filter(x=>x.text)}
async function parsePdfRich(file){await loadScriptOnce('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js',()=>!!window.pdfjsLib);window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';const pdf=await window.pdfjsLib.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise,out=[];for(let i=1;i<=pdf.numPages;i++){const pg=await pdf.getPage(i),tc=await pg.getTextContent(),lines=pdfTextLines(tc.items);for(const line of lines){const text=normalizeImportedText(line.text);if(!text)continue;out.push({type:isSectionHeading(text)?'heading':'paragraph',text})}if(i<pdf.numPages)out.push({type:'separator'})}return{text:blocksToPlainText(out),blocks:out,warnings:['PDF reconstruido por líneas y coordenadas. Se detectan encabezados CJK comunes, pero revisa saltos, ilustraciones y ruby antes de publicar.']}}
function normalizeImportedText(t){return String(t||'').replace(/\r\n?/g,'\n').replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').trim()}
function normalizeSectionHeadingText(v){return String(v||'').normalize('NFKC').replace(/[\u00a0\u3000]+/g,' ').replace(/\s+/g,' ').trim()}
function detectSectionType(t){t=normalizeSectionHeadingText(t).toLowerCase();if(/pr[oó]logo|prologue|プロローグ|序章|序幕/.test(t))return'prologue';if(/ep[ií]logo|epilogue|エピローグ|終章|終幕/.test(t))return'epilogue';if(/interludio|interlude|幕間|間章|閑話/.test(t))return'interlude';if(/afterword|あとがき|後書き|posfacio|nota del autor/.test(t))return'afterword';if(/extra|bonus|特典|番外|外伝|短編|特別編|書き下ろし|後日談|口絵|挿絵|illustrations?|ilustraciones?|gallery/.test(t))return'extra';return'chapter'}
function isSectionHeading(text){const t=normalizeSectionHeadingText(text);if(!t||t.length>140)return false;return /^(?:(?:cap[ií]tulo|chapter|episode|episodio|scene|act)\s*(?:[0-9]+|[ivxlcdm]+)\b.*|第?\s*(?:[0-9]+|[一二三四五六七八九十百千万〇零]+)\s*(?:章|話|節|部|巻|幕|編).*|(?:一|二|三|四|五|六|七|八|九|十|百)+\s*(?:章|話).*|序章.*|序幕.*|終章.*|終幕.*|前章.*|後章.*|pr[oó]logo.*|prologue.*|プロローグ.*|ep[ií]logo.*|epilogue.*|エピローグ.*|interludio.*|interlude.*|幕間.*|間章.*|閑話.*|afterword.*|あとがき.*|後書き.*|extra.*|bonus.*|番外.*|外伝.*|短編.*|特別編.*|書き下ろし.*|後日談.*|口絵.*|挿絵.*|illustrations?.*|ilustraciones?.*|gallery.*)$/i.test(t)}
function detectSectionsRich(blocks,text){const source=(blocks||[]).length?blocks:textBlocks(text),out=[];let title='Capítulo 1',buf=[];const push=()=>{const clean=buf.filter(Boolean);if(clean.length)out.push({title,section_type:detectSectionType(title),blocks:clean,body:blocksToPlainText(clean)})};for(const raw of source){const b=normalizeImportBlock(raw),candidate=(b.type==='heading'||b.type==='paragraph')&&isSectionHeading(b.text);if(candidate){push();title=normalizeSectionHeadingText(b.text);buf=[]}else buf.push(b)}push();if(!out.length&&source.length)out.push({title:'Capítulo 1',section_type:'chapter',blocks:source.map(normalizeImportBlock),body:blocksToPlainText(source)});return out.map((x,i)=>({...x,section_number:i+1}))}
function renumberImportSections(){S.importState.sections=(S.importState.sections||[]).map((x,i)=>({...x,section_number:i+1}))}
function importMoveSection(i,dir){syncStructureFields();const a=S.importState.sections,j=i+dir;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];renumberImportSections();render()}
function importDeleteSection(i){syncStructureFields();S.importState.sections.splice(i,1);renumberImportSections();render()}
function importMergePrevious(i){syncStructureFields();if(i<=0)return;const a=S.importState.sections,prev=a[i-1],cur=a[i];prev.blocks=[...(prev.blocks||[]),...(cur.blocks||[])];prev.body=blocksToPlainText(prev.blocks);a.splice(i,1);renumberImportSections();render()}
function importSplitAtCursor(i){syncEditedBodies();const sec=S.importState.sections[i],el=document.querySelector('[data-sec-body="'+i+'"]');if(!sec||!el)return;let p=el.selectionStart||0;if(p<=0||p>=el.value.length){toast('Coloca el cursor dentro del texto donde quieras dividir.','bad');return}const left=el.value.slice(0,p).trim(),right=el.value.slice(p).trim();if(!left||!right){toast('La división debe dejar texto en ambas partes.','bad');return}sec.body=left;sec.blocks=textBlocks(left);const next={...sec,title:(sec.title||'Capítulo')+' · continuación',body:right,blocks:textBlocks(right)};S.importState.sections.splice(i+1,0,next);renumberImportSections();render()}
function detectSections(text){return detectSectionsRich([],text)}
function syncStructureFields(){$$('[data-sec-title]').forEach(el=>{const i=+el.dataset.secTitle;if(S.importState.sections[i])S.importState.sections[i].title=el.value.trim()||`Sección ${i+1}`});$$('[data-sec-type]').forEach(el=>{const i=+el.dataset.secType;if(S.importState.sections[i])S.importState.sections[i].section_type=el.value})}
function syncImportTarget(){const t=$('#importTranslation'),v=$('#importVolumeNumber'),n=$('#importVolumeTitle'),a=$('#importExistingAction');if(t)S.importState.translationId=t.value;if(v)S.importState.volumeNumber=v.value||'1';if(n)S.importState.volumeTitle=n.value.trim();if(a)S.importState.existingAction=a.value}
function syncEditedBodies(){$('[data-sec-body]').forEach(el=>{const i=+el.dataset.secBody,sec=S.importState.sections[i];if(!sec)return;const next=el.value,previous=blocksToPlainText(sec.blocks||[]);sec.body=next;if(next!==previous)sec.blocks=textBlocksPreserveImportedMedia(next,sec.blocks||[])})}
function syncImportFields(){syncStructureFields();syncImportTarget();syncEditedBodies()}
function textBlocks(body){return String(body||'').split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean).map(x=>importTextBlock(x,'paragraph')).filter(Boolean)}
function textBlocksPreserveImportedMedia(body,previous=[]){const images=(previous||[]).filter(b=>b.type==='image'),parts=String(body||'').split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean);let imageIndex=0;return parts.map(x=>{if(/^\[Ilustración(?::[^\]]+)?\]$/i.test(x)&&images[imageIndex])return normalizeImportBlock(images[imageIndex++]);return importTextBlock(x,'paragraph')}).filter(Boolean)}
async function loadStudioData(){if(!S.groups.length){S.studioTranslations=[];return}const ids=S.groups.map(g=>g.translator_groups?.id).filter(Boolean);if(!ids.length)return;S.studioTranslations=await jreq(`/rest/v1/translations?group_id=in.(${ids.join(',')})&select=id,title,status,language_code,group_id,editorial_mode,novels(id,title),translator_groups(id,name)&order=updated_at.desc`)||[]}
function importCanonicalText(v){return normalizeImportedText(String(v||'')).normalize('NFKC').toLowerCase().replace(/\s+/g,' ').trim()}
function importFingerprint(title,blocks){const raw=importCanonicalText(title)+'\n'+importCanonicalText(blocksToPlainText((blocks||[]).map(normalizeImportBlock)));let h=2166136261;for(let i=0;i<raw.length;i++){h^=raw.charCodeAt(i);h=Math.imul(h,16777619)}return(h>>>0).toString(36)+':'+raw.length}
async function rollbackImportedPaths(paths){let failed=0;for(const path of [...new Set(paths||[])].reverse())try{await storageDelete(path)}catch{failed++}return failed}
async function saveImportDrafts(){const I=S.importState;if(I.busy)return;I.busy=true;I.message='';render();let jobId=null,uploadedPaths=[],backup=[],volume=null;try{syncImportFields();const tr=S.studioTranslations.find(x=>x.id===I.translationId);if(!tr)throw new Error('Proyecto no disponible.');const gid=tr.group_id||tr.translator_groups?.id,job=await jreq('/rest/v1/import_jobs',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({group_id:gid,created_by:S.user.id,filename:I.name,file_type:I.type,status:'processing',result:{section_count:I.sections.length}})});jobId=job?.[0]?.id||null;let vols=await jreq('/rest/v1/volumes?translation_id=eq.'+I.translationId+'&volume_number=eq.'+encodeURIComponent(I.volumeNumber)+'&select=id,title,volume_number&limit=1'),existing=[];volume=vols?.[0];if(!volume){const created=await jreq('/rest/v1/volumes',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({translation_id:I.translationId,volume_number:Number(I.volumeNumber),title:I.volumeTitle||null,status:'draft'})});volume=created?.[0]}else{existing=await jreq('/rest/v1/sections?volume_id=eq.'+volume.id+'&select=id,section_type,section_number,title,content,sort_order,status,published_at,updated_at&order=sort_order.asc')||[];backup=existing.map(x=>({section_type:x.section_type,section_number:x.section_number,title:x.title,content:x.content,sort_order:x.sort_order,status:x.status,published_at:x.published_at}));if(existing.length&&I.existingAction==='replace'){if(!confirm('Este volumen ya tiene '+existing.length+' secciones. Se guardará un respaldo técnico en el registro de importación antes de reemplazarlas. ¿Continuar?'))throw new Error('Importación cancelada.');if(jobId)await jreq('/rest/v1/import_jobs?id=eq.'+jobId,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({result:{section_count:I.sections.length,backup_volume_id:volume.id,backup_sections:backup},updated_at:new Date().toISOString()})});await jreq('/rest/v1/sections?volume_id=eq.'+volume.id,{method:'DELETE',headers:{Prefer:'return=minimal'}});existing=[]}}if(!volume?.id)throw new Error('No se pudo resolver el volumen.');let nextNumber=existing.reduce((m,x)=>Math.max(m,Number(x.section_number)||0),0),nextSort=existing.reduce((m,x)=>Math.max(m,Number(x.sort_order)||0),0),duplicates=0;const known=new Set(existing.map(x=>importFingerprint(x.title,Array.isArray(x.content)?x.content:[]))),payload=[];for(let i=0;i<I.sections.length;i++){const x=I.sections[i],raw=(x.blocks?.length?x.blocks.map(normalizeImportBlock):textBlocks(x.body)),fingerprint=importFingerprint(x.title,raw);if(I.existingAction==='append'&&known.has(fingerprint)){duplicates++;continue}known.add(fingerprint);const content=await materializeImportedImages(raw,gid,'volume-'+volume.id+'-section-'+(nextSort+1),uploadedPaths);nextNumber++;nextSort++;payload.push({volume_id:volume.id,section_type:x.section_type,section_number:nextNumber,title:x.title,content,sort_order:nextSort,status:'draft'})}if(payload.length)await jreq('/rest/v1/sections',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(payload)});if(jobId)await jreq('/rest/v1/import_jobs?id=eq.'+jobId,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status:'completed',result:{section_count:payload.length,skipped_duplicates:duplicates,volume_id:volume.id,translation_id:I.translationId,existing_action:I.existingAction,backup_sections:I.existingAction==='replace'?backup:undefined},updated_at:new Date().toISOString()})});I.busy=false;I.message='Importación completada: '+payload.length+' secciones guardadas'+(duplicates?' · '+duplicates+' duplicado(s) exacto(s) omitido(s)':'')+'.';render()}catch(e){const rollbackFailed=await rollbackImportedPaths(uploadedPaths);if(jobId)try{await jreq('/rest/v1/import_jobs?id=eq.'+jobId,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status:'failed',result:{error:String(e?.message||e).slice(0,500),rolled_back_files:uploadedPaths.length-rollbackFailed,rollback_failed:rollbackFailed,backup_volume_id:volume?.id||null,backup_sections:backup.length?backup:undefined},updated_at:new Date().toISOString()})})}catch{}I.busy=false;I.message=friendlyError(e,'No se pudo guardar la importación.')+(rollbackFailed?' Algunos archivos temporales no pudieron limpiarse.':'');render()}}


function setReaderPref(k,v){S.readerPrefs[k]=v;const keys={fontSize:'reader_font',theme:'reader_theme',width:'reader_width',lineHeight:'reader_line_height',fontFamily:'reader_font_family',paragraphSpace:'reader_paragraph_space'};localStorage.setItem(keys[k]||('reader_'+k),String(v));render()}
function resetReaderPrefs(){S.readerPrefs={theme:'light',fontSize:18,width:'normal',lineHeight:'comfortable',fontFamily:'serif',paragraphSpace:'normal'};['reader_theme','reader_font','reader_width','reader_line_height','reader_font_family','reader_paragraph_space'].forEach(k=>localStorage.removeItem(k));render();toast('Preferencias de lectura restablecidas.','ok')}
async function loadFollows(){if(!S.user){S.follows=[];return}S.follows=await jreq(`/rest/v1/follows?user_id=eq.${S.user.id}&select=target_type,target_id,created_at`)||[]}
async function toggleFollow(type,id){try{if(!S.user){go('auth');return}if(isFollowing(type,id)){await jreq(`/rest/v1/follows?user_id=eq.${S.user.id}&target_type=eq.${type}&target_id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}})}else{await jreq('/rest/v1/follows',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({user_id:S.user.id,target_type:type,target_id:id})})}await loadFollows();render()}catch(e){toast(friendlyError(e),'bad')}}
async function loadReaderComments(sectionId){const rows=await jreq(`/rest/v1/comments?section_id=eq.${sectionId}&select=id,section_id,user_id,parent_id,body,is_spoiler,created_at,profiles(id,username,display_name),comment_reactions(user_id,reaction)&order=created_at.asc`);S.readerComments=(rows||[]).map(c=>({...c,like_count:(c.comment_reactions||[]).filter(r=>r.reaction==='like').length,liked_by_me:!!S.user&&(c.comment_reactions||[]).some(r=>r.user_id===S.user.id&&r.reaction==='like')}))}
async function postComment(parentId=null,bodyOverride=null){try{if(!S.user||!S.readerSection)return;const body=(bodyOverride ?? $('#newCommentBody')?.value?.trim() ?? '');if(body.length<1){toast('Escribe un comentario.','bad');return}const is_spoiler=parentId?false:!!$('#newCommentSpoiler')?.checked;await jreq('/rest/v1/comments',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({section_id:S.readerSection.id,user_id:S.user.id,parent_id:parentId,body,is_spoiler})});await loadReaderComments(S.readerSection.id);render();toast('Comentario publicado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function replyComment(id){const body=prompt('Escribe tu respuesta:');if(body&&body.trim())await postComment(id,body.trim())}
async function toggleCommentLike(id){try{if(!S.user){go('auth');return}const c=S.readerComments.find(x=>x.id===id);if(c?.liked_by_me){await jreq(`/rest/v1/comment_reactions?comment_id=eq.${id}&user_id=eq.${S.user.id}&reaction=eq.like`,{method:'DELETE',headers:{Prefer:'return=minimal'}})}else{await jreq('/rest/v1/comment_reactions',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({comment_id:id,user_id:S.user.id,reaction:'like'})})}await loadReaderComments(S.readerSection.id);render()}catch(e){toast(friendlyError(e),'bad')}}
async function reportComment(id){if(!S.user){go('auth');return}const reason=prompt('Motivo del reporte:');if(!reason?.trim())return;try{await jreq('/rest/v1/comment_reports',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({comment_id:id,reporter_id:S.user.id,reason:reason.trim(),status:'pending'})});toast('Reporte enviado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function openDetail(id){if(String(id).startsWith('demo-')){S.currentDetail=null;go('detail:'+id);return}try{S.currentDetail=await loadTranslationDetail(id);go('detail:'+id)}catch(e){toast(friendlyError(e),'bad')}}
async function loadTranslationDetail(id){const rows=await jreq(`/rest/v1/translations?id=eq.${id}&select=id,title,status,language_code,popularity_score,updated_at,novels(id,title,synopsis,cover_url,author_name,genres,tags),translator_groups(id,name),volumes(id,volume_number,title,status,cover_url,sections(id,title,section_type,section_number,status,sort_order),download_links(id,format,provider,url))&limit=1`);const x=rows?.[0]||null;if(!x||!['active','complete','paused'].includes(x.status))return null;const publicVolumeIds=new Set((x.volumes||[]).filter(v=>v.status==='published').map(v=>v.id));const [purchase,support,downloads]=await Promise.all([jreq(`/rest/v1/purchase_links?novel_id=eq.${x.novels?.id}&is_verified=eq.true&select=id,volume_number,store_name,region,language_code,format,url&order=volume_number.asc`),x.translator_groups?.id?jreq(`/rest/v1/support_links?group_id=eq.${x.translator_groups.id}&select=id,label,url&order=created_at.asc`):Promise.resolve([]),publicVolumeIds.size?jreq(`/rest/v1/download_links?volume_id=in.(${[...publicVolumeIds].join(',')})&select=id,volume_id,format,provider,url&order=created_at.asc`):Promise.resolve([])]);x.links={purchase:purchase||[],support:support||[],downloads:(downloads||[]).filter(l=>publicVolumeIds.has(l.volume_id))};return x}

async function uploadPersonalAvatar(e){try{const file=e.target.files?.[0];if(!file||!S.user)return;const url=await storageUpload(file,`users/${S.user.id}/avatar/${mediaStableName('avatar',file)}`,true);const input=$('#profileAvatarUrl');if(input)input.value=url;toast('Avatar subido. Guarda el perfil para aplicarlo.','ok')}catch(err){toast(friendlyError(err),'bad')}}
async function savePersonalProfile(){try{if(!S.user)return;const oldAvatar=S.profile?.avatar_url||null,username=$('#profileUsername')?.value.trim().replace(/^@/,'')||null;if(username&&(!/^[A-Za-z0-9_.-]{3,40}$/.test(username))){toast('El nombre de usuario debe tener 3-40 caracteres y usar letras, números, punto, guion o guion bajo.','bad');return}const body={display_name:$('#profileDisplayName')?.value.trim()||null,username,avatar_url:$('#profileAvatarUrl')?.value.trim()||null,bio:$('#profileBio')?.value.trim()||null,public_library:!!$('#profilePublicLibrary')?.checked,public_activity:!!$('#profilePublicActivity')?.checked,updated_at:new Date().toISOString()};await jreq(`/rest/v1/profiles?id=eq.${S.user.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify(body)});await loadUser();if(oldAvatar&&oldAvatar!==body.avatar_url)await deleteOldMediaIfUnused(oldAvatar);render();toast('Perfil actualizado.','ok')}catch(e){const m=String(e?.message||'');toast(/duplicate|23505/i.test(m)?'Ese nombre de usuario ya está en uso.':friendlyError(e),'bad')}}
async function openPublicProfile(id){try{S.publicProfile=await loadPublicProfileData(id);go('profile:'+id)}catch(e){toast(friendlyError(e),'bad')}}
async function openGroup(id){try{S.publicGroup=await loadPublicGroupData(id);go('group:'+id)}catch(e){toast(friendlyError(e),'bad')}}

function roleLabel(role){return({owner:'Owner',admin:'Admin',translator:'Traductor',editor:'Editor',proofreader:'Corrector',collaborator:'Colaborador'}[role]||role||'Miembro')}
function myGroupRole(groupId){return S.groups.find(g=>g.translator_groups?.id===groupId)?.role||null}
function isCurrentGroupEditor(groupId){return ['owner','admin','translator','editor'].includes(myGroupRole(groupId))||S.admin}
function isCurrentGroupManager(groupId){return ['owner','admin'].includes(myGroupRole(groupId))||S.admin}
function editorialGroups(){return S.groups.filter(g=>isCurrentGroupEditor(g.translator_groups?.id))}
async function loadTeamMembers(groupId){S.teamMembers=await jreq(`/rest/v1/group_members?group_id=eq.${groupId}&select=group_id,user_id,role,profiles(id,username,display_name,avatar_url)&order=role.asc`)||[]}
async function resolveProfileByUsername(value){const raw=String(value||'').trim().replace(/^@/,'');if(!raw)return null;let rows=await jreq(`/rest/v1/profiles?username=eq.${encodeURIComponent(raw)}&select=id,username,display_name&limit=1`);if(rows?.[0])return rows[0];if(/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(raw)){rows=await jreq(`/rest/v1/profiles?id=eq.${raw}&select=id,username,display_name&limit=1`);return rows?.[0]||null}return null}
async function addTeamMember(){try{const G=S.studioTeam;if(!G||!isCurrentGroupManager(G.id)){toast('No tienes permiso para administrar miembros.','bad');return}const profile=await resolveProfileByUsername($('#memberUsername')?.value);if(!profile){toast('No encontramos ese nombre de usuario.','bad');return}const role=$('#memberRole')?.value||'translator';if(role==='owner'){toast('El owner no se asigna desde aquí.','bad');return}await jreq('/rest/v1/group_members',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({group_id:G.id,user_id:profile.id,role})});await loadTeamMembers(G.id);await loadStudioData();render();toast(`${profile.display_name||profile.username||'Usuario'} fue agregado al equipo.`,'ok')}catch(e){const m=String(e?.message||'');toast(/duplicate|23505/i.test(m)?'Ese usuario ya pertenece al equipo.':friendlyError(e),'bad')}}
async function changeTeamMemberRole(userId,role){try{const G=S.studioTeam;if(!G||!isCurrentGroupManager(G.id)||role==='owner')return;const m=S.teamMembers.find(x=>x.user_id===userId);if(!m||m.role==='owner')return;await jreq(`/rest/v1/group_members?group_id=eq.${G.id}&user_id=eq.${userId}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({role})});await loadTeamMembers(G.id);await loadStudioData();render();toast('Rol actualizado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function removeTeamMember(userId){try{const G=S.studioTeam;if(!G||!isCurrentGroupManager(G.id))return;const m=S.teamMembers.find(x=>x.user_id===userId);if(!m||m.role==='owner'){toast('El owner del equipo está protegido.','bad');return}await jreq(`/rest/v1/group_members?group_id=eq.${G.id}&user_id=eq.${userId}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});await loadTeamMembers(G.id);await loadStudioData();render();toast('Acceso retirado.','ok')}catch(e){toast(friendlyError(e),'bad')}}

async function openMediaLibrary(groupId,target=null){try{if(!groupId)throw new Error('No se pudo determinar el equipo.');if(!isCurrentGroupEditor(groupId))throw new Error('Tu rol no puede gestionar la biblioteca multimedia.');S.mediaGroupId=groupId;S.mediaTarget=target;S.mediaQuery='';S.mediaPage=0;S.mediaUsage={};S.mediaLoading=true;go('studio:media:'+groupId);render();S.mediaFiles=await storageWalk(`teams/${groupId}`);await loadMediaUsage(S.mediaFiles.map(x=>x.path));S.mediaLoading=false;render()}catch(e){S.mediaLoading=false;toast(friendlyError(e),'bad')}}
function mediaBack(){const gid=S.mediaGroupId,target=S.mediaTarget;S.mediaTarget=null;if(target&&S.studioProject?.group_id===gid)go('studio:project:'+S.studioProject.id);else if(S.studioTeam?.id===gid)go('studio:team:'+gid);else go('studio')}
async function uploadMediaLibraryFile(file){try{if(!file||!S.mediaGroupId)return;const path=`teams/${S.mediaGroupId}/library/${storageName('media',file)}`;await storageUpload(file,path,false);S.mediaFiles=await storageWalk(`teams/${S.mediaGroupId}`);await loadMediaUsage(S.mediaFiles.map(x=>x.path));S.mediaPage=0;render();toast('Imagen añadida a la biblioteca.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function useMediaAsset(path){try{const url=storagePublicUrl(path),t=S.mediaTarget;if(!t){await copyMediaUrl(path);return}if(t==='team-avatar'){await jreq(`/rest/v1/translator_groups?id=eq.${S.mediaGroupId}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({avatar_url:url,updated_at:new Date().toISOString()})});S.studioTeam=await loadStudioTeam(S.mediaGroupId);S.mediaTarget=null;go('studio:team:'+S.mediaGroupId);toast('Avatar actualizado.','ok');return}if(t==='team-banner'){await jreq(`/rest/v1/translator_groups?id=eq.${S.mediaGroupId}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({banner_url:url,updated_at:new Date().toISOString()})});S.studioTeam=await loadStudioTeam(S.mediaGroupId);S.mediaTarget=null;go('studio:team:'+S.mediaGroupId);toast('Banner actualizado.','ok');return}if(t==='novel-cover'){if(!S.studioProject?.novels?.id)throw new Error('No hay proyecto activo.');await jreq(`/rest/v1/novels?id=eq.${S.studioProject.novels.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({cover_url:url,updated_at:new Date().toISOString()})});S.mediaTarget=null;await refreshStudioProject();go('studio:project:'+S.studioProject.id);toast('Portada actualizada.','ok');return}if(t.startsWith('volume-cover:')){const id=t.split(':')[1];await jreq(`/rest/v1/volumes?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({cover_url:url,updated_at:new Date().toISOString()})});S.mediaTarget=null;await refreshStudioProject();go('studio:project:'+S.studioProject.id);toast('Portada del volumen actualizada.','ok');return}if(t.startsWith('block:')){const i=Number(t.split(':')[1]);if(!S.blockEditor?.blocks?.[i])throw new Error('El bloque ya no está disponible.');S.blockEditor.blocks[i].url=url;S.mediaTarget=null;go('studio:project:'+S.studioProject.id);toast('Ilustración seleccionada.','ok');return}}catch(e){toast(friendlyError(e),'bad')}}
async function copyMediaUrl(path){try{const url=storagePublicUrl(path);if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(url);else{const ta=document.createElement('textarea');ta.value=url;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove()}toast('URL copiada.','ok')}catch(e){toast('No se pudo copiar la URL.','bad')}}
async function deleteMediaAsset(path){try{if(!path)return;if(S.mediaUsage?.[path]===undefined)await loadMediaUsage([path]);if(Number(S.mediaUsage?.[path]||0)>0){toast('No puedes eliminar esta imagen porque todavía está siendo usada.','bad');return}await storageDelete(path);S.mediaFiles=S.mediaFiles.filter(x=>x.path!==path);delete S.mediaUsage[path];render();toast('Archivo eliminado de Storage.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function cleanupOrphanMedia(){try{await loadMediaUsage(S.mediaFiles.map(x=>x.path));const orphan=S.mediaFiles.filter(x=>Number(S.mediaUsage?.[x.path]||0)===0);if(!orphan.length){toast('No hay archivos huérfanos.','ok');return}if(!confirm(`Se eliminarán ${orphan.length} archivo(s) sin referencias. ¿Continuar?`))return;let removed=0,failed=0;for(const f of orphan){try{await storageDelete(f.path);removed++;delete S.mediaUsage[f.path]}catch{failed++}}S.mediaFiles=await storageWalk(`teams/${S.mediaGroupId}`);await loadMediaUsage(S.mediaFiles.map(x=>x.path));S.mediaPage=0;render();toast(failed?`${removed} eliminados; ${failed} no pudieron borrarse.`:`${removed} archivos huérfanos eliminados.`,failed?'bad':'ok')}catch(e){toast(friendlyError(e),'bad')}}async function storageSelfTest(){try{if(!S.mediaGroupId)throw new Error('Abre primero una biblioteca de equipo.');const prefix=`teams/${S.mediaGroupId}/_tests`,name=`storage-e2e-${Date.now().toString(36)}.png`,path=`${prefix}/${name}`,a=await testPngFile(1,name),b=await testPngFile(5,name);await storageUpload(a,path,false);let rows=await storageListFolder(prefix,0,200),first=rows.find(x=>x.name===name);if(!first)throw new Error('INSERT no apareció en el listado.');const firstSize=Number(first.metadata?.size||0);await storageUpload(b,path,true);rows=await storageListFolder(prefix,0,200);const second=rows.find(x=>x.name===name);if(!second)throw new Error('UPDATE/upsert eliminó el objeto inesperadamente.');const secondSize=Number(second.metadata?.size||0);if(firstSize===secondSize)console.warn('El tamaño del archivo de prueba no cambió; el upsert sí respondió correctamente.');await storageDelete(path);rows=await storageListFolder(prefix,0,200);if(rows.some(x=>x.name===name))throw new Error('DELETE no eliminó el objeto de prueba.');toast('Storage E2E correcto: subir, reemplazar, listar y borrar.','ok')}catch(e){toast('Prueba Storage: '+friendlyError(e),'bad')}}

async function openStudioTeam(id){try{S.studioTeam=await loadStudioTeam(id);await loadTeamMembers(id);go('studio:team:'+id)}catch(e){toast(friendlyError(e),'bad')}}
async function loadStudioTeam(id){const rows=await jreq(`/rest/v1/translator_groups?id=eq.${id}&select=id,slug,name,description,avatar_url,banner_url,primary_color,secondary_color&limit=1`);const g=rows?.[0];if(!g)return null;g.support_links=await jreq(`/rest/v1/support_links?group_id=eq.${id}&select=id,label,url&order=created_at.asc`)||[];return g}
async function refreshStudioTeam(){if(!S.studioTeam?.id)return;S.studioTeam=await loadStudioTeam(S.studioTeam.id);await loadTeamMembers(S.studioTeam.id);await loadStudioData();render()}
async function uploadTeamMedia(e,kind){try{const G=S.studioTeam,file=e.target.files?.[0];if(!G||!file)return;const url=await storageUpload(file,`teams/${G.id}/profile/${mediaStableName(kind,file)}`,true);const input=$(kind==='avatar'?'#teamEditAvatar':'#teamEditBanner');if(input)input.value=url;toast(kind==='avatar'?'Avatar subido.':'Banner subido.','ok')}catch(err){toast(friendlyError(err),'bad')}}
async function saveStudioTeamProfile(){try{const G=S.studioTeam;if(!G)return;const oldAvatar=G.avatar_url||null,oldBanner=G.banner_url||null,body={name:$('#teamEditName')?.value.trim()||G.name,description:$('#teamEditDescription')?.value.trim()||null,avatar_url:$('#teamEditAvatar')?.value.trim()||null,banner_url:$('#teamEditBanner')?.value.trim()||null,primary_color:$('#teamEditPrimary')?.value.trim()||null,secondary_color:$('#teamEditSecondary')?.value.trim()||null,updated_at:new Date().toISOString()};await jreq(`/rest/v1/translator_groups?id=eq.${G.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify(body)});await refreshStudioTeam();if(oldAvatar&&oldAvatar!==body.avatar_url)await deleteOldMediaIfUnused(oldAvatar);if(oldBanner&&oldBanner!==body.banner_url)await deleteOldMediaIfUnused(oldBanner);toast('Perfil del equipo actualizado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function addSupportLink(){try{const G=S.studioTeam,label=$('#supportLabel')?.value.trim(),url=$('#supportUrl')?.value.trim();if(!G||!label||!url){toast('Completa etiqueta y URL.','bad');return}if(safeUrl(url)==='#'){toast('La URL no es válida.','bad');return}await jreq('/rest/v1/support_links',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({group_id:G.id,label,url:safeUrl(url)})});await refreshStudioTeam();toast('Enlace de apoyo agregado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function deleteSupportLink(id){try{await jreq(`/rest/v1/support_links?id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});await refreshStudioTeam();toast('Enlace eliminado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function addPurchaseLink(){try{const P=S.studioProject,store_name=$('#purchaseStore')?.value.trim(),url=$('#purchaseUrl')?.value.trim();if(!P||!store_name||!url){toast('Completa tienda y URL.','bad');return}if(safeUrl(url)==='#'){toast('La URL no es válida.','bad');return}const volumeRaw=$('#purchaseVolume')?.value;await jreq('/rest/v1/purchase_links',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({novel_id:P.novels.id,group_id:P.group_id,volume_number:volumeRaw?Number(volumeRaw):null,store_name,region:$('#purchaseRegion')?.value.trim()||null,language_code:$('#purchaseLanguage')?.value.trim()||null,format:$('#purchaseFormat')?.value.trim()||null,url:safeUrl(url),is_verified:false})});await refreshStudioProject();toast('Enlace enviado para verificación.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function deletePurchaseLink(id){try{await jreq(`/rest/v1/purchase_links?id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});await refreshStudioProject();toast('Enlace eliminado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function addDownloadLink(){try{const P=S.studioProject,volume_id=$('#downloadVolume')?.value,format=$('#downloadFormat')?.value.trim(),url=$('#downloadUrl')?.value.trim();if(!P||!volume_id||!format||!url){toast('Completa volumen, formato y URL.','bad');return}if(safeUrl(url)==='#'){toast('La URL no es válida.','bad');return}await jreq('/rest/v1/download_links',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({volume_id,format,provider:$('#downloadProvider')?.value.trim()||null,url:safeUrl(url)})});await refreshStudioProject();toast('Descarga agregada.','ok')}catch(e){toast(friendlyError(e),'bad')}}
